/**
 * Allele-design notes for each indexed gene x modification page.
 * One paragraph per gene and modification class, distinct from the gene-level intro.
 * Key format: `${mouseSymbol}:${modSlug}`. No em or en dashes.
 */

export const geneModNotes: Record<string, string> = {
  'Trp53:conditional-knockout':
    'Trp53 nulls survive to adulthood, so the argument for a conditional is not viability but attribution and timing: germline nulls succumb to thymic lymphoma by six months, which censors the slower epithelial tumors most projects actually want. Floxing exons 2 through 10 removes the transactivation domains and the entire DNA-binding core, giving a clean deletion rather than a truncated peptide that could retain tetramerization. Pair the allele to the compartment: Pdx1-Cre or p48-Cre with an LSL-Kras allele for pancreatic ductal disease, inhaled adenoviral Cre for lung, K14-Cre or WAP-Cre for mammary, GFAP-Cre for glioma. Cre itself provokes a p53-dependent damage response, so Cre-only littermates are not optional. Read out latency and spectrum, but also confirm function directly: irradiate sorted recombined cells and show failed Cdkn1a and Mdm2 induction alongside karyotypic instability.',
  'Trp53:knockout':
    'Unlike most genes on this list, complete germline deletion of Trp53 is compatible with development, which makes the straight null the cheapest sensitizing background available and the correct choice when the question is suppressor dosage rather than tissue of origin. Homozygotes die of thymic lymphoma within roughly six months; heterozygotes live longer and develop osteosarcoma and soft tissue sarcoma after losing the remaining allele, which is the closest genetic mimic of Li-Fraumeni syndrome. Two caveats govern interpretation. Strain background shifts the spectrum substantially, so cohorts must be backcrossed and reported, and a fraction of female homozygotes show exencephaly, meaning expected Mendelian ratios at weaning are not a reliable genotyping check. Confirm loss of heterozygosity by sequencing or allele-specific PCR in heterozygote tumors, and report survival as a spectrum-annotated curve rather than a single median.',
  'Trp53:knockin':
    'Knockins are where Trp53 modeling gets discriminating, but only if the mutation sits at the endogenous locus under native regulation, since transgenic overexpression manufactures gain-of-function that endogenous alleles do not show. Two mechanistic classes should not be conflated. Contact substitutions leave the beta-sandwich folded and remove base contacts in the major groove; structural substitutions destabilize the core fold and expose surfaces that sequester p63 and p73. Beyond hotspots, transactivation-domain mutants that ablate the two amino-terminal activation subdomains, and lysine-substituted acetylation-site alleles, separate arrest and metabolic outputs from classical apoptosis, which is the cleaner experiment when asking what suppression actually requires. Expect mutant protein to accumulate only in tumor tissue, because Mdm2 still degrades it in normal cells, so immunohistochemistry for stabilized p53 is an on-target readout rather than a validation of the allele. Sequence-confirm the knockin transcript.',
  'Trp53:humanized':
    'Humanization of Trp53 is worth doing for a narrow set of questions and wasteful for the rest. The DNA-binding core is highly conserved, so pathway biology rarely changes; what does change is chemistry and epitope. Compounds that act by covalent modification of core cysteines, and antibodies raised against human amino-terminal or carboxy-terminal epitopes, behave differently on the mouse protein, and the codon 72 proline-arginine polymorphism that modifies apoptotic threshold has no mouse equivalent. The proline-rich region also diverges in repeat number. A partial swap in which the human DNA-binding core exons replace the mouse equivalents keeps native regulation and mouse-specific interactions intact while allowing human missense variants and carcinogen-induced mutation spectra to be scored directly in primary fibroblasts. Full-locus humanization is only justified when isoform structure or the internal promoter matters. Verify human transcript expression and confirm normal Cdkn1a induction before running any cohort.',
  'Brca1:conditional-knockout':
    'The choice inside the conditional class matters more than the choice of the class for Brca1. Deleting the large central exon leaves the RING and BRCT modules translated in frame and reproduces the naturally occurring internally deleted splice isoform, which retains partial resection and RAD51 loading capacity and is a documented route to PARP inhibitor resistance; a true null flox around the RING-encoding exons or the terminal BRCT exons avoids that escape. Driver choice carries its own traps. MMTV-Cre lines differ in penetrance and recombine in salivary gland, hematopoietic cells and occasionally the germline, so genotype tail and non-target tissue in every cohort; K14-Cre hits basal epithelium broadly; WAP-Cre requires parity to express. Endpoints should include RAD51 and gammaH2AX focus formation after irradiation in sorted mammary epithelium, not tumor latency alone, since latency conflates deletion efficiency with selection.',
  'Brca1:knockout':
    'A straight germline null is not a cohort-generating allele for Brca1; it is a reagent. Homozygotes arrest early in gastrulation with a proliferation block and secondary p53 activation, and the commonly cited suppressor-loss rescue extends survival by days without producing viable animals, so any experiment must be run on timed-mating embryos or on derived cell lines. Heterozygotes are the other surprise: they are largely tumor-free across a normal lifespan, unlike human carriers, which is itself a result worth stating rather than a failed model. Where the null earns its keep is as a null background for complementation, since embryonic stem cells lacking endogenous Brca1 support quantitative rescue assays that score human missense variants by viability, RAD51 focus restoration and olaparib sensitivity. If you need lifetime tumor data, use the conditional. Stage embryos precisely and confirm deletion at the transcript level, not by genomic PCR alone.',
  'Brca1:knockin':
    'Point knockins are the only way to ask which Brca1 activity a given human variant actually breaks, but they impose two design constraints. First, a single amino-acid change at the zinc-coordinating cysteines of the RING collapses folding and BARD1 binding, whereas a surface substitution on the RING face that contacts the E2 enzyme removes catalysis while leaving the heterodimer intact; those two alleles give opposite answers about whether ubiquitin transfer is required for suppression, so state which one you are building. Second, many pathogenic human alleles act through splicing rather than protein chemistry, and a codon-only edit into mouse exonic context will silently fail to reproduce exon skipping. Where splicing is suspected, humanize the affected exon and its flanking intronic sequence. Score homologous recombination directly with a reporter substrate and olaparib dose-response curves, and test 53BP1 epistasis before drawing resistance conclusions.',
  'Brca1:humanized':
    'Brca1 is one of the genes where humanization is defensible rather than cosmetic, because mouse and human coding sequence diverge substantially outside the RING and BRCT modules, and variant-of-uncertain-significance work performed on mouse residues does not transfer cleanly. The practical problem is size. Full-locus replacement spans a large multi-exon region and risks disturbing promoter and intronic regulatory elements, so most projects are better served by cassette humanization of the specific module under study, leaving the remainder murine. Whichever scale you choose, the non-negotiable validation is rescue: the humanized allele must support development to term over a null, otherwise every downstream variant score is measured against a broken baseline. Beyond viability, confirm BARD1 heterodimer formation by co-immunoprecipitation and normal RAD51 focus kinetics. Only then are the humanized animals usable for antibody-dependent assays or for scoring clinical variants against PARP inhibitor and platinum response.',
  'Brca2:conditional-knockout':
    'Conditional deletion of Brca2 is dominated by one practical problem: recombined cells that lack p53 support are counter-selected, and tumors that eventually appear are frequently escapers that retained an unrecombined allele. Every cohort therefore needs allele-specific PCR on tumor DNA, ideally on laser-captured epithelium, to confirm that the lesion is genuinely null. Which exons you flank determines what question the allele can answer. Removing the BRC repeat exon abolishes RAD51 monomer loading and collapses homologous recombination outright. Deleting only the carboxy-terminal exon that carries the filament-stabilizing site leaves recombination broadly intact while stripping stalled fork protection, which is the cleaner allele for asking whether fork degradation alone drives chemosensitivity. For drivers, K14-Cre and beta-lactoglobulin-Cre give basal and luminal mammary targeting respectively, and Pdx1-Cre serves pancreatic work. Score nascent strand degradation by DNA fiber assay alongside tumor latency.',
  'Brca2:knockout':
    'For Brca2 the complete null is best treated as a benchmark rather than a model. Homozygotes fail before mid-gestation with a cell-autonomous proliferation arrest, and unlike some suppressor pathways this lethality is not meaningfully relieved by removing checkpoint genes, so no amount of background engineering converts the null into a tumor cohort. Heterozygotes are phenotypically unremarkable and should not be used as carrier surrogates. The design that repays the effort is a knockout-first cassette allele: the trapped configuration behaves as a graded hypomorph, useful for asking how much residual protein development tolerates, then Flp removal converts it to a clean conditional and Cre exposure converts it to a null, all from one line. If you build a straight null, its main purpose is complementation of embryonic stem cells and derived fibroblasts. Verify by transcript quantification, and stage lethality with timed matings.',
  'Brca2:knockin':
    'Two knockin classes cover most legitimate Brca2 questions and they are not interchangeable. Substituting the CDK-phosphorylated serine in the carboxy-terminal RAD51 filament-binding site leaves homologous recombination essentially intact but abolishes protection of stalled forks, producing animals that are recombination-proficient and still chemosensitive; that dissociation is the entire point and cannot be obtained from any deletion allele. Substitutions in the DNA-binding domain that disrupt the DSS1 interface instead destabilize the protein and mislocalize it, so they behave closer to hypomorphs and should be interpreted as such. Practically, the coding sequence is very large, targeting arms are awkward, and any selection cassette left in an intron can depress expression enough to masquerade as a variant effect, so remove it and quantify transcript before phenotyping. Read out nascent strand degradation, RAD51 focus formation, and platinum and PARP inhibitor dose-response in matched primary cells.',
  'Brca2:humanized':
    'Full humanization of Brca2 is technically the hardest job in this set because the locus and coding sequence are both very large, and the payoff has to be weighed carefully. Conservation is moderate overall, but the eight BRC repeats and the DSS1-binding fold are similar enough that mouse partners engage human sequence, which is why bacterial artificial chromosome complementation can support development over a null. That rescue is the correct validation gate: an allele that does not restore viability is not reporting variant function, it is reporting a construction defect. For most variant interpretation programs a modular swap of the exons encoding the region under study is faster, cheaper and less disruptive to endogenous splicing than whole-locus replacement. Once viable, phenotype the line for RAD51 focus kinetics, sister chromatid exchange and drug response, and sequence the humanized segment across its full length.',
  'Pten:conditional-knockout':
    'Because Pten loss is dose-sensitive and haploinsufficiency already produces phenotypes, conditional work should be designed to compare heterozygous and homozygous recombined tissue in the same experiment rather than treating deletion as binary. Flank the exons encoding the catalytic core, including the CX5R signature of the phosphatase active site, so the deleted allele cannot yield a partially active fragment. Driver selection sets the disease: probasin-Cre for prostate, with the caveat that this line is transmitted through males and shows activity outside the prostate that must be documented; Nestin-Cre or GFAP-Cre for the macrocephaly, seizure and social behavior phenotypes; Villin-Cre for intestinal polyposis. The dominant confound in prostate is senescence induced by acute complete loss, which stalls lesions at high-grade intraepithelial neoplasia, so include senescence-associated beta-galactosidase staining alongside phospho-AKT and phospho-S6 immunohistochemistry before concluding that a modifier suppressed tumorigenesis.',
  'Pten:knockout':
    'The germline heterozygote, not the homozygote, is the usable null-derived animal for Pten. Complete loss stops development around the time of gastrulation with patterning failure, so homozygous tissue is only accessible through embryos, chimeras or derived cells. Heterozygotes are informative but noisy in a specific way: they develop lymphoid hyperplasia and an autoimmune, lymphoproliferative syndrome with splenomegaly and autoantibody production that can kill animals before the epithelial lesions of interest mature. Cohorts therefore need palpation and hematology schedules and clear censoring rules, otherwise survival curves report immune disease rather than cancer. Female heterozygotes reliably develop endometrial lesions, which makes the uterus a high-yield tissue for modifier screens. Do not assume classical two-hit kinetics; many lesions arise with the wild-type allele retained, so quantify residual protein by immunoblot or immunohistochemistry rather than genotyping the tumor and stopping there.',
  'Pten:knockin':
    'Beyond catalytic mutants, the informative Pten knockins live in the regulatory regions rather than the active site. Alanine substitution across the carboxy-terminal serine and threonine phosphorylation cluster locks the protein in the open conformation, increasing membrane association and net lipid phosphatase output, which is the only clean way to ask whether tonic autoinhibition constrains signaling in vivo. Truncating the extreme carboxy-terminal PDZ-binding motif detaches the protein from MAGI and MAST scaffolds without touching catalysis. Substituting the lysines that carry mono-ubiquitin redirects the protein between nucleus and cytosol and separates chromatin-associated functions from PIP3 hydrolysis. Every one of these edits can change steady-state abundance, so immunoblot matched tissue and normalize before attributing a phenotype to activity rather than dose. Pair phospho-AKT and phospho-S6 readouts with subcellular fractionation, since a mislocalized but catalytically intact protein produces a misleadingly null-like signaling profile.',
  'Pten:humanized':
    'This is the case where humanization is usually the wrong purchase. Mouse and human PTEN coding sequences are near-identical across the phosphatase and C2 domains, so nearly every clinically reported missense variant maps onto an identical mouse residue, and a single-codon knockin into the endogenous mouse locus gives the same answer faster, cheaper and with native regulation preserved. Antibody cross-reactivity is likewise not a limiting problem. Two situations do justify humanizing sequence. If the question concerns untranslated region biology, including pseudogene-directed competing endogenous RNA regulation and the human-specific arrangement of that locus, then the coding region is irrelevant and the untranslated regions are what must be swapped. If the question concerns the alternatively initiated extended isoform translated from an upstream non-canonical start, the human 5 prime leader is required. Otherwise, build the variant knockin and spend the saved effort on Cre driver validation and cohort size.',
  'Myc:conditional-knockout':
    'Conditional Myc deletion is straightforward to build, since essentially all coding sequence sits in the second and third exons and a single floxed cassette removes the entire protein, but it is treacherous to interpret. Null cells are outcompeted by their unrecombined neighbors within weeks, so any conditional cohort must carry a lineage reporter and be scored as a competitive assay, not as a tissue phenotype. Match the driver to a compartment where the requirement is testable: interferon-inducible Mx1-Cre or Vav-Cre for hematopoiesis, where loss traps stem cells in the niche and blocks differentiation; Alb-Cre for hepatocytes, where regeneration proceeds surprisingly well and reveals paralog compensation; a ubiquitous tamoxifen-inducible driver for adult systemic withdrawal. Expect Mycn to substitute in some lineages, so measure both transcripts. Useful endpoints are cell size, nucleolar area and ribosomal RNA synthesis rather than proliferation index alone.',
  'Myc:knockout':
    'A germline Myc null is a developmental reagent, not a cohort. Homozygotes arrest around embryonic day 9.5 to 10.5 with defective yolk sac vasculature, failed primitive erythropoiesis, and cardiac and neural tube abnormalities, and the vascular defect is largely non-cell-autonomous, which means embryo phenotypes cannot be read as a direct cell-intrinsic requirement. The heterozygote is the more interesting animal and is often overlooked: reduced dosage yields smaller mice with altered metabolic and inflammatory profiles and extended median lifespan, which makes it a clean tool for asking what tonic Myc levels cost an organism. If a homozygous null cell is what you need, derive it rather than breed it, using inducible deletion in cultured fibroblasts or stem cells so the acute transcriptional collapse can be captured before compensation. Score embryos by precise somite staging and whole-mount vascular labeling, not gross morphology.',
  'Myc:knockin':
    'Knockins at the endogenous Myc locus should be reserved for questions that dosage manipulation cannot answer, because the locus tolerates very little change in output before secondary selection begins. Two structural edits are worth the effort. Deleting the conserved second Myc box strips Trrap and cofactor recruitment and separates transformation from viability, since the mutant protein still dimerizes and binds DNA. A substitution in the helix-loop-helix surface that abolishes Miz1 contact while preserving Max heterodimerization isolates target repression from activation, which no deletion allele can do. Anticipate that any allele raising net activity engages the Arf and p53 apoptotic brake, so tumor phenotypes will require that axis to be compromised and cohorts should be designed with that cross from the start. Critically, quantify transcription with spike-in normalized sequencing, because standard normalization mathematically erases global amplification.',
  'Myc:humanized':
    'Coding humanization of Myc buys very little. The Myc boxes, the phosphodegron serine and threonine pair, and the basic helix-loop-helix leucine zipper are essentially invariant between mouse and human, so a humanized protein behaves like the endogenous one and mechanism does not change. The defensible targets are elsewhere. Sequence-dependent therapeutics such as antisense oligonucleotides and small interfering RNA require exact human transcript sequence, and immunological work on peptide epitopes requires both human coding sequence and a matched human leukocyte antigen background, so those programs need the swap. The other real case is regulatory: the human risk-associated enhancers lying far upstream and downstream of the gene body are not conserved in position or sequence, and studying them means humanizing that noncoding interval rather than the exons. Decide which of these applies, then validate by confirming normal protein turnover kinetics after growth factor stimulation.',
  'Kras:conditional-knockout':
    'The most useful application of a Kras conditional is not loss-of-function phenotyping but dependency testing, because widespread deletion in adult animals is tolerated even though the same deletion in the embryo is lethal, and that timing difference is itself the result. Flanking the first coding exon removes both alternatively spliced products, so the allele cannot leave a partially functional isoform behind. Two experiments justify the build. Deleting the remaining wild-type allele in a mutant-driven tumor tests whether normal Kras restrains the oncogenic one, a genetic relationship that copy-number data alone cannot establish. Deleting the oncogenic allele after tumors are established tests maintenance rather than initiation. A whole-body tamoxifen-inducible driver suits the first question; tissue-restricted drivers such as Pdx1-Cre or Lyz2-Cre suit lineage work. Confirm recombination in sorted tumor cells and read out phospho-ERK and phospho-AKT alongside regression kinetics.',
  'Kras:knockout':
    'A complete Kras null is chiefly a benchmark for essentiality, since homozygotes die in mid to late gestation with anemia, thinned ventricular myocardium and motor neuron loss, and heterozygotes are unremarkable. The more informative deletion is isoform-selective. Removing only the alternative fourth exon that generates the palmitoylated minor isoform leaves animals viable and healthy, which establishes that the constitutively spliced major isoform carries the developmental requirement, and it converts a lethal gene into a tractable one for asking what the minor isoform contributes to tumor initiation and to membrane trafficking through a palmitoylation cycle rather than the polybasic route. That allele is worth building before a full null in most programs. If a full null is required, plan timed matings with hematological and cardiac assessment at defined stages, and confirm on a defined background, since gestational lethality windows shift with strain.',
  'Kras:knockin':
    'Substitution identity, not just position, determines what a Kras knockin can test. Glycine to cysteine retains measurable intrinsic hydrolysis and continues to cycle, which is why covalent agents that engage the inactive state can work at all; aspartate and valine substitutions cycle poorly and require chemically distinct approaches, and glutamine 61 substitutions block the catalytic machinery itself. Build the allele that matches the drug class you intend to test rather than defaulting to the most common one. Two construction choices matter. A stop cassette upstream of the mutant exon must be verified as tight, because low-level leak produces sporadic lesions that confound latency comparisons, and a Flp-responsive rather than Cre-responsive cassette frees Cre for a second lesion in the same animal. Track allelic imbalance during progression by sequencing tumor complementary DNA, and confirm activation by Ras-GTP pulldown rather than phospho-ERK alone.',
  'Kras:humanized':
    'Amino acid humanization of Kras is close to redundant. The catalytic G domain, including the switch regions and the pocket exploited by covalent inhibitors, is identical between mouse and human, so compound binding, potency and resistance mutations translate without any sequence swap; the few divergent residues sit in the hypervariable tail and affect membrane behavior rather than drug contact. If the goal is testing clinical compounds, build the corresponding oncogenic knockin and skip humanization entirely. Humanization becomes worthwhile only when the nucleotide sequence itself is the subject. Human coding sequence carries a strongly biased set of rare codons that holds protein output low, and the untranslated regions carry microRNA sites and structured elements absent or divergent in mouse, so translational regulation, RNA-targeting therapeutics and expression-level questions all require the human sequence. Validate by measuring protein per transcript, not transcript alone.',
  'Apc:conditional-knockout':
    'Conditional deletion is the only practical route for Apc in adult tissue, but note what the standard floxed exon 14 design actually produces: Cre excision creates a frameshift and a truncated product retaining the amino-terminal oligomerization region and some 15 amino acid repeats, not a clean null, so the allele models human truncating mutations rather than protein absence. Driver choice sets the phenotype more than the allele does. Lgr5-EGFP-IRES-CreERT2 restricts loss to crypt base columnar cells and yields discrete adenomas, whereas Villin-CreERT2 or AhCre deletes across the whole epithelium and kills animals within days from crypt hyperproliferation and malabsorption, so titrate tamoxifen for mosaicism. Read out nuclear beta-catenin, Axin2 and Lgr5 in situ, crypt fission counts, and Wnt-ligand-independent growth of derived organoids in medium lacking R-spondin.',
  'Apc:knockout':
    'A constitutive null is only informative in heterozygosity here. Homozygous Apc-null embryos arrest before gastrulation completes, so the homozygous state is accessible only in embryoid bodies, blastocyst outgrowths, or derived ES lines. The heterozygote is the useful animal: somatic loss of the remaining allele drives multifocal adenomas, giving a quantitative tumor multiplicity readout that is unusually sensitive to genetic background. Modifier effects at Pla2g2a mean C57BL/6 and AKR or BALB/c congenics differ several fold in polyp count, so fix and report the background before comparing cohorts. Expect disease concentrated in small intestine rather than colon, which limits fidelity to human familial adenomatous polyposis and argues for adding a colitis or azoxymethane challenge. Score polyp number and diameter by region under a dissecting scope, confirm loss of heterozygosity by sequencing microdissected lesions, and stain for nuclear beta-catenin.',
  'Apc:knockin':
    'Knockin is the instrument that makes Apc genetics quantitative, because phenotype tracks the number of 20 amino acid repeats and SAMP motifs retained rather than presence or absence of protein. Placing a stop codon proximal to the mutation cluster region leaves few repeats and gives strong Wnt output, while a distal stop preserves repeats and yields an intermediate setpoint consistent with the just-right signaling model. Two other designs answer questions no truncation can. Deleting only the SAMP repeats removes AXIN docking while sparing beta-catenin binding, isolating destruction complex assembly. Removing the C-terminal EB1 and DLG interaction sites leaves Wnt regulation intact and tests whether spindle and chromosome instability contribute independently to tumor progression. Build these as conditional inversion or lox-stop-lox alleles to avoid embryonic lethality, then quantify Axin2 transcript levels, cytoplasmic versus nuclear beta-catenin, and anaphase bridge frequency.',
  'Apc:humanized':
    'There is no therapeutic antibody or small molecule directed at APC, the protein is entirely intracellular, and the domain architecture is well conserved between species, so whole-gene humanization buys nothing and is impractical for a coding sequence of this size. The defensible exception is sequence-level humanization of short segments where the human nucleotide context itself is the phenotype. The I1307K variant found in Ashkenazi Jewish carriers converts a stretch into a homopolymeric adenine tract prone to polymerase slippage, generating somatic truncations, and only the human sequence reproduces that instability. Similar logic applies to human splice donor and acceptor variants and to premature termination codons targeted by nonsense readthrough or antisense exon-skipping compounds, which are strictly sequence-matched. Otherwise choose a truncation knockin series. If you do humanize a cassette, verify normal transcript splicing and steady state destruction complex activity before interpreting any tumor difference.',
  'Rb1:conditional-knockout':
    'Because germline loss kills embryos through placental and erythroid failure, the conditional allele is the default, and it is worth remembering that even conditional deletion often does little alone: Rbl1 and Rbl2 substitute at many E2F targets, so single-gene retinal deletion with Chx10-Cre gives hyperplasia rather than retinoblastoma unless Rbl2 is also removed. In lung, the productive design pairs floxed Rb1 with floxed Trp53 and delivers Cre by intratracheal adenovirus or lentivirus, which yields small cell carcinoma with neuroendocrine markers after a long latency; adding a Pten or Myc allele shortens it. Titrate viral dose, since initiation frequency drives tumor number and confounds survival comparisons. Confirm excision by PCR on sorted or laser captured tumor cells, then read out E2F target transcripts, EdU incorporation, Ascl1 and Neurod1 subtype markers, and absence of phosphorylated RB.',
  'Rb1:knockout':
    'The straight null is still worth making, but its value is developmental rather than oncologic. Homozygotes die in midgestation, and tetraploid aggregation or wild-type placental rescue restores much of the neuronal and erythroid apoptosis phenotype, which established that a large part of the classic embryonic lethality is non-cell-autonomous and secondary to trophoblast failure. That experiment remains the cleanest use of the allele. Heterozygotes are viable and undergo somatic loss of the wild-type copy, but the tumor spectrum is pituitary intermediate lobe melanotroph adenoma and thyroid C cell neoplasia, not retinoblastoma, so do not present the strain as a model of the human syndrome. It does serve as a sensitized background for modifier screens and carcinogen studies. Genotype carefully to distinguish null from conditional alleles, verify absence of protein by immunoblot, and time embryo collection precisely because lethality is strain shifted.',
  'Rb1:knockin':
    'This is where Rb1 genetics gets precise, because the pocket protein has two separable interaction surfaces and a phosphorylation code layered on top. Substituting the CDK consensus serines and threonines with alanine yields a constitutively hypophosphorylated protein that cannot be inactivated by cyclin D with CDK4 or CDK6, giving a clean genetic test of whether palbociclib-class benefit requires RB and whether unrestrained RB is tolerated in proliferative tissue. Independently, point substitutions in the B box groove abolish LXCXE binding while leaving the E2F transactivation domain cleft intact, separating chromatin modifier recruitment and viral oncoprotein sequestration from direct E2F repression. Introduce these at the endogenous locus rather than as transgenes, since stoichiometry matters. Confirm phosphorylation state by mobility shift, measure E2F target derepression, test HDAC1 and SUV39H1 co-immunoprecipitation, and assay E7 or large T antigen binding as a functional readout of the mutated groove.',
  'Rb1:humanized':
    'Humanization is a poor fit here. RB is a nuclear scaffold with no antibody or small molecule directed against it, CDK4 and CDK6 inhibitors act on the kinases rather than on RB, and those inhibitors engage the mouse enzymes perfectly well, so nothing in the therapeutic pipeline requires a human coding sequence. The real species difference is not sequence identity but paralog compensation: mouse retina tolerates RB loss because Rbl1 and Rbl2 cover the same E2F targets, and swapping in human RB1 does not change that. Compound conditional genetics remains the correct fix. Narrow humanization is defensible only when the human nucleotide context is itself the object of study, for example low-penetrance promoter variants, splice site alterations, or missense alleles being evaluated for pathogenicity classification. In those cases humanize the affected exon and flanking intron only, and confirm normal splicing and protein abundance in unchallenged animals.',
  'Egfr:conditional-knockout':
    'Deleting the receptor is the cleaner genetic maneuver than removing ligands, because seven agonists including Egf, Tgfa, Areg, Hbegf, Ereg, Btc and Epgn converge on it and single ligand nulls are usually silent. Floxing the exons encoding the kinase domain removes catalytic output while avoiding a stable truncated ectodomain that could still dimerize. Choose the driver by tissue: K14-Cre or K5-CreERT2 for epidermis, Villin-CreERT2 for intestinal regeneration after irradiation or dextran sulfate injury, Scgb1a1-CreER or Sftpc-CreERT2 for airway and alveolar epithelium, hGFAP-Cre for glia. Be aware that epidermal deletion produces severe dermatitis with systemic inflammation and weight loss, which contaminates any downstream immune or metabolic readout, so use inducible drivers and short intervals. Score phosphorylated EGFR, ERK and AKT, wound closure or crypt regeneration kinetics, and confirm excision at the protein level rather than by tail genotyping.',
  'Egfr:knockout':
    'A constitutive null is unusually background dependent and that fact should drive the decision. On some strains embryos fail around implantation, on 129 they die in midgestation from placental spongiotrophoblast deficiency, and on outbred or C57BL/6 backgrounds pups survive to birth then die within weeks with immature lung, skin and gut epithelium and progressive neurodegeneration. Any cohort comparison therefore requires a fixed, declared background and littermate controls, and rederivation onto a second strain is often informative in itself. For adult questions the null is the wrong tool; the naturally occurring waved-2 hypomorph, a kinase domain substitution that lowers but does not abolish catalytic activity, is viable and gives graded signaling reduction. Use the null for placental morphometry, lung branching counts, and epidermal barrier assays at defined embryonic and neonatal stages, and confirm complete loss of receptor protein rather than relying on transcript measurement.',
  'Egfr:knockin':
    'Mutant knockin at the endogenous locus is the strongest EGFR allele available, and it works because the kinase domain is close enough between species that erlotinib, gefitinib and osimertinib engage the mouse enzyme. Build the exon 19 deletion or the L858R substitution behind a lox-stop-lox cassette so expression stays under the native promoter, then initiate with intratracheal adenoviral Cre or a Scgb1a1-CreER driver rather than a doxycycline-inducible transgene, which overexpresses and distorts dose response. Layering T790M or C797S in cis produces defined first and third generation resistance, and vIII requires a separate ectodomain deletion design for glioma work. Sequence the recombined allele to confirm the mutation sits in cis with the deleted stop cassette. Endpoints are tumor volume by micro computed tomography before and during drug, phosphorylated EGFR and ERK, time to progression, and sequencing of resistant lesions.',
  'Egfr:humanized':
    'This is the allele that matters most for translational work, because cetuximab, panitumumab and necitumumab do not recognize mouse ERBB1, and neither do EGFR-directed antibody-drug conjugates or the EGFR arm of bispecifics such as amivantamab. Swap the entire extracellular region, domains I through IV, in frame at the endogenous locus rather than replacing only the domain III epitope, since partial swaps often misfold or disturb the tether that holds the receptor autoinhibited. Retain the mouse transmembrane and cytoplasmic segments so downstream coupling and any existing conditional or mutant alleles remain usable. Human EGFR responds to mouse ligands, so basal physiology is generally preserved, but confirm normal skin, hair and body weight before dosing. Because the humanized receptor is expressed in normal epithelium, this strain also reports on-target skin and gut toxicity, which xenografts cannot. Measure receptor occupancy, phosphorylation, and dermatologic scoring alongside tumor response.',
  'Erbb2:conditional-knockout':
    'Two questions justify a conditional here, and they are different. For cardiac safety, deletion with Myh6-Cre or an inducible Myh6-MerCreMer produces chamber dilation and reduced contractility, the genetic counterpart of anthracycline-sensitized trastuzumab cardiotoxicity; note that tamoxifen dosing of MerCreMer lines is itself cardiotoxic, so include Cre-positive oil-treated controls. For Schwann cell and neuromuscular work, Dhh-Cre or Mpz-Cre removes the neuregulin 1 type III receptor complex and yields hypomyelination measured by g ratio and nerve conduction. In mammary studies, MMTV-Cre lines differ substantially: line D shows germline and hematopoietic activity that silently converts animals to constitutive heterozygotes, so genotype offspring for the recombined allele every generation, and consider WAP-Cre for lactation-restricted timing. Because ERBB2 signals only in heterodimers, interpret loss against parallel Erbb3 deletion. Endpoints are serial echocardiography, phosphorylated AKT, and ductal branching morphometry.',
  'Erbb2:knockout':
    'The straight null is an embryonic tool, not a cancer tool. Homozygotes arrest around midgestation with a smooth-walled ventricle that never forms trabeculae, because cardiac neuregulin 1 from endocardium cannot signal to myocardial ERBB2 with ERBB4. The lethality is early enough that every later question, including neural crest derived Schwann cell precursor survival, sensory and motor ganglion formation, and neuromuscular junction assembly, is invisible unless heart function is restored. The established workaround is a cardiac-restricted rescue transgene that carries embryos to birth and unmasks the peripheral nervous system phenotype. Heterozygotes are essentially normal and give no useful oncologic readout, since human disease is driven by amplification and gain of function rather than haploinsufficiency. Use this allele for staged embryo collection with histology of the ventricular wall, whole mount neurofilament staining, and in situ analysis of Nrg1 and Erbb4 expression.',
  'Erbb2:knockin':
    'Knockin is the right class for Erbb2 because the human disease is gain of function, and because expression level determines whether the phenotype is physiologic or artifactual. Placing an activating allele under the endogenous promoter, using a lox-stop-lox or inversion cassette so that a mammary Cre switches it on, avoids the supraphysiologic output of MMTV promoter transgenes. Two design families are worth separating: the transmembrane valine to glutamate substitution originally described in rat neu, which forces covalent dimerization, and the clinically observed kinase domain variants including exon 20 insertions and the leucine to serine and valine to leucine substitutions that confer differential sensitivity to lapatinib, neratinib and tucatinib. Tumors arising from endogenous promoter alleles frequently amplify the mutant copy, so quantify allele copy number in lesions. Track latency, multiplicity, pulmonary metastasis, phosphorylated ERBB2 and AKT, and regression kinetics under each inhibitor.',
  'Erbb2:humanized':
    'Full ectodomain replacement is the decisive allele. Trastuzumab binds subdomain IV, pertuzumab binds the subdomain II dimerization arm, and biparatopic agents such as zanidatamab need both, so swapping a single subdomain is inadequate; replace domains I through IV in frame at the endogenous locus and keep the mouse transmembrane and kinase regions so heterodimerization with mouse EGFR and ERBB3 is preserved. Verify that the humanized receptor still adopts the extended conformation by confirming ligand-independent heterodimer formation and baseline phosphorylated AKT. The payoff is twofold. Antibody-drug conjugates including trastuzumab emtansine and trastuzumab deruxtecan can be tested where normal heart, gut and lung express the human epitope, so on-target off-tumor toxicity and bystander killing become measurable rather than assumed. Cardiac endpoints belong in the same study: serial echocardiography with and without anthracycline exposure, troponin, and myofibrillar histology.',
  'Pdcd1:conditional-knockout':
    'The reason to build this rather than use the null is timing and compartment. PD-1 is expressed transiently during thymic selection and on activated B cells, NK cells, and some myeloid populations, so a germline deletion mixes developmental and effector phenotypes. Cd4-Cre already acts at the double positive stage and carries that confound; E8i-Cre restricts loss to CD8 lineage cells after selection, and Ncr1-Cre or Cd19-Cre isolates NK and B contributions. More useful still is an inducible driver such as Gzmb-CreERT2 or a tamoxifen dependent ubiquitous line, which lets you delete after exhaustion is established and ask whether the program is reversible rather than merely preventable. Include tamoxifen-treated Cre-positive controls, since tamoxifen alters lymphocyte numbers. Read out antigen-specific tetramer frequency, TOX, TCF1 and TIM3 co-expression, interferon gamma and TNF production per cell, and tumor or viral load.',
  'Pdcd1:knockout':
    'The germline null is viable and remains genuinely useful, mainly as an on-target specificity control: an anti-PD-1 antibody that still alters tumor growth in these animals is acting through something other than the receptor. Interpretation depends entirely on background. On C57BL/6, autoimmunity appears late as lupus-like glomerulonephritis with immune complex deposition; on BALB/c, animals develop dilated cardiomyopathy associated with autoantibodies against cardiac troponin I; on NOD, diabetes onset accelerates sharply. State the background and the age at analysis, because a young cohort will look unremarkable. The null also exaggerates responses in chronic LCMV clone 13 infection and worsens experimental autoimmune encephalomyelitis, which makes it a sensitized platform for testing whether a second checkpoint contributes. Endpoints are proteinuria and renal histology, echocardiographic fractional shortening, autoantibody titer, viral titer, and antigen-specific CD8 expansion with cytokine measurement.',
  'Pdcd1:knockin':
    'Two very different knockins are worth building. The first is mechanistic: substituting phenylalanine for the tyrosine in the membrane-distal ITSM abolishes SHP2 recruitment while leaving surface expression and ligand binding intact, which separates inhibitory signaling from receptor occupancy and provides the genetic test of whether checkpoint antibodies act by blocking ligand or by other means. Mutating the membrane-proximal ITIM tyrosine in parallel establishes the relative weight of the two motifs. Given that CD28 is the preferred substrate, pair these alleles with phosphoflow for CD28 and Lck-proximal components rather than assuming TCR readouts will report the defect. The second is a reporter or driver knockin, GFP or tdTomato in frame at the locus for tracking, or an inducible Cre for lineage tracing exhausted cells into progenitor and terminal subsets. Confirm the knockin does not reduce surface density, since expression level itself sets inhibitory strength.',
  'Pdcd1:humanized':
    'This is the mandatory allele for testing clinical antibodies, since pembrolizumab, nivolumab, cemiplimab and dostarlimab bind epitopes absent from the mouse receptor, and those epitopes are not confined to one loop: nivolumab engages the N-terminal region while pembrolizumab depends on the C prime D loop. Replace the entire immunoglobulin variable ectodomain encoded by the second coding exon and retain the mouse transmembrane segment and cytoplasmic tail so that ITSM signaling through murine SHP2 is unchanged. The known caveat is cross-species ligand affinity: human PD-1 binds mouse PD-L1 less avidly, which can leave the axis partially disengaged at baseline, so confirm that unchallenged animals show normal T cell numbers and no early autoimmunity, and consider pairing with a humanized Cd274 allele. Because isotype effects depend on Fc receptor engagement, state the constant region used. Endpoints are receptor occupancy, tumor growth, and infiltrating lymphocyte phenotype.',
  'Cd274:conditional-knockout':
    'The unresolved question this allele answers is which cell enforces suppression, since tumor cells, dendritic cells, macrophages and endothelium all display the ligand and bone marrow chimeras cannot separate them cleanly. Flox the exon encoding the IgV domain so any residual product cannot engage PD-1. Itgax-Cre addresses conventional dendritic cells but also removes ligand from alveolar macrophages and a fraction of T cells, and Lyz2-Cre is notoriously incomplete in tissue resident macrophages, so quantify deletion by flow cytometry on each sorted population rather than trusting the driver. Cdh5-CreERT2 isolates the endothelial barrier contribution to lymphocyte entry. One confound deserves attention: PD-L1 binds CD80 in cis on the same antigen presenting cell, so deleting it liberates CD80 for CD28 and can increase costimulation independent of PD-1. Measure CD80 availability, CD8 infiltration, interferon gamma responses, and tumor growth in parallel.',
  'Cd274:knockout':
    'Whole-body loss is viable and gives a clean upper bound on what ligand blockade can achieve, which makes it the correct specificity control for atezolizumab-class reagents in humanized crosses. Two design facts matter. First, PD-L2 remains and engages PD-1 with higher affinity, so a single null underestimates the pathway; a true pathway null requires removing Pdcd1lg2 as well, and because the two genes sit adjacent on the same chromosome you cannot obtain the double mutant by intercrossing independently derived lines, you must target both in cis. Second, phenotypes are provocation dependent: unchallenged animals look normal, whereas experimental autoimmune encephalomyelitis is worse, NOD diabetes accelerates, and hepatic and islet CD8 tolerance fails. Endpoints should therefore include a defined challenge, with antigen-specific CD8 expansion and cytokine production, target organ histology, and transplantable tumor growth measured against antibody blockade in wild-type hosts.',
  'Cd274:knockin':
    'Knockin is the way to attack regulation rather than presence, which is where most of the unanswered biology sits. A fluorescent or luciferase reporter placed in frame at the locus lets you watch interferon gamma driven induction in real time across tumor, stroma and draining node, something antibody staining after tissue dissociation cannot provide. Deleting the IRF1 binding element in the regulatory region yields an allele that retains basal expression but cannot be induced, separating constitutive from inflammation-driven suppression. Truncating the three prime untranslated region reproduces the structural variants that stabilize the transcript in human lymphoma and gives a genetic overexpression model at endogenous copy number. Finally, substitutions on the face that contacts CD80 while sparing the PD-1 interface separate cis inhibition from trans signaling. Read out surface protein by flow, transcript stability by actinomycin chase, and T cell function in co-culture and in tumor-bearing animals.',
  'Cd274:humanized':
    'Humanization here serves two purposes that the mouse ligand cannot. Atezolizumab, durvalumab and avelumab bind the human IgV face and have no murine cross-reactivity, and separately the diagnostic antibody clones used to score expression in patients recognize only human PD-L1, so a humanized allele is the only way to test a companion diagnostic staining protocol on tissue where expression is regulated normally rather than driven by a transgene. Replace the IgV and IgC2 ectodomain in frame and keep the mouse transmembrane and cytoplasmic regions so CMTM6 mediated recycling is unperturbed. Because human PD-L1 engages mouse PD-1 with reduced affinity, pair this with a humanized Pdcd1 allele when quantitative blockade is the endpoint. Avelumab is an IgG1 capable of antibody-dependent cellular cytotoxicity, so state the Fc format and consider Fc gamma receptor humanization. Score induction after interferon gamma, receptor occupancy, and lymphocyte function.',
  'Ctla4:conditional-knockout':
    'Because germline nulls die before four weeks, essentially every adult question about CD152 requires a floxed allele. Flank the exon encoding the IgV ectodomain so recombination removes ligand binding rather than only the tail, and build a separate tail-only allele if the YVKM trafficking motif is the actual target. Foxp3-YFP-Cre gives regulatory T cell restricted deletion, and because Foxp3 is X-linked, use hemizygous males or genotype female mosaics carefully. Cd4-CreERT2 with tamoxifen allows deletion after thymic selection is complete, which separates developmental from maintenance requirements. Deletion in regulatory cells alone reproduces much of the lethality, so stagger dosing and plan survival curves rather than a single fixed timepoint. Score CD80 and CD86 surface density on dendritic cells as the direct cell-extrinsic readout, with Ki67 and effector cytokines in conventional T cells, plus blinded histology of heart and pancreas.',
  'Ctla4:knockout':
    'The straight null is not a tool for chronic experiments, it is a short and violent phenotype: multiorgan lymphoproliferation, myocarditis, pancreatitis, and death within three to four weeks, so readouts must be collected in a narrow window before wasting confounds them. Deleting the exons encoding the ectodomain and transmembrane segment gives an unambiguous protein null rather than a truncated species that could still dimerize. Heterozygotes are more useful for translational work, since reduced dosage models human CTLA4 insufficiency with variable lymphocytic infiltration and incomplete penetrance that itself demands large cohorts. Kinetics shift with strain, so fix background and use littermate controls before comparing groups. Informative endpoints are survival, weight curves, expansion of CD44 high CD62L low populations, autoantibody titers, and blinded histopathology across heart, pancreas, lung and salivary gland rather than scoring one tissue.',
  'Ctla4:knockin':
    'Point knockins are the way to separate what CD152 does from where it sits. Mutating the tyrosine within the cytoplasmic YVKM motif blocks AP-2 capture and traps the receptor at the surface, raising steady-state ligand stripping while eliminating the endosomal recycling that LRBA normally sustains, a clean genetic test of whether trafficking or occupancy limits suppression. Mutating the MYPPPY ligand motif does the opposite, leaving trafficking intact but abolishing CD80 and CD86 engagement. Patient-derived missense substitutions in the IgV domain are also worth building, since they usually reduce protein rather than abolish it and therefore behave unlike a null. Confirm expression by paired intracellular and surface flow cytometry on the same cells, quantify transendocytosis using labelled CD80 in coculture, and keep littermate wild-type controls because these alleles are hypomorphic to differing degrees.',
  'Ctla4:humanized':
    'Clinical anti-CTLA-4 antibodies do not bind mouse CD152, so any pharmacology question requires a humanized allele. Replacing the exon encoding the IgV ectodomain while retaining mouse transmembrane and cytoplasmic sequence preserves AP-2 dependent internalization and LRBA recycling, which matters because in vivo potency depends on the receptor cycling back to the surface, not on affinity alone. Full-locus replacement is possible but risks altering trafficking kinetics and complicates comparison with existing mouse data. Because regulatory T cell depletion through Fc gamma receptor engagement is a leading mechanism for ipilimumab activity, cross to human Fc gamma receptor transgenic mice before attributing efficacy to blockade. Endpoints should include plasma exposure, receptor occupancy on tumor-infiltrating regulatory cells, intratumoral regulatory to CD8 ratio, syngeneic tumor growth, and colitis or hypophysitis-like toxicity on a fixed background.',
  'Lag3:conditional-knockout':
    'Because germline nulls are viable and nearly silent, a floxed Lag3 allele earns its cost only when the question is compartmental. Flank the exons encoding D1 with its extra loop so recombination removes MHC class II binding rather than trimming the stalk. E8I-Cre restricts deletion to the CD8 lineage and is the right driver for cell-intrinsic exhaustion during chronic LCMV clone 13 or in tumors, though its recombination is frequently incomplete, so sort and PCR rather than trusting reported penetrance. Foxp3-Cre addresses the regulatory T cell arm, and Slc6a3-Cre suits questions about fibrillar alpha-synuclein uptake by dopaminergic neurons rather than immunology. With Cd4-CreERT2, dose tamoxifen before priming, since LAG-3 is induction dependent and late deletion leaves protein already at the synapse. Read out tetramer-positive CD8 numbers, interferon gamma and TNF co-production, TOX and TCF1 distribution, and viral or tumor burden.',
  'Lag3:knockout':
    'A straight null is cheap, viable, and mostly uninformative alone, which is precisely why it is worth making: its purpose is as a crossing partner, not a standalone model. Delete the whole coding block rather than part of it, because LAG-3 is normally shed by ADAM10 and ADAM17 and a partial allele could leave a soluble decoy that confounds interpretation. Informative phenotypes appear in compound genetics, most reliably with Pdcd1 loss, where double nulls develop lethal myocarditis on permissive backgrounds while staying comparatively healthy on C57BL/6, so background must be declared and fixed rather than assumed. Homeostatic characterization will look negative, so plan challenge instead. Useful endpoints are chronic LCMV clone 13 viral titers, diabetes incidence on NOD, cardiac troponin with histology in compound mutants, and tumor rejection kinetics alongside matched single-mutant arms.',
  'Lag3:knockin':
    'Because LAG-3 signals without classical ITIMs, separating its parts is best done with precise substitutions rather than deletion. A cleavage-resistant allele mutating the ADAM10 and ADAM17 site in the connecting peptide keeps the receptor at the surface and tests whether shedding is a genuine off switch. Mutating the cytoplasmic FSAL motif, or removing the glutamate proline repeat, leaves ligand binding intact while disabling inhibitory output, which distinguishes competition for peptide MHC class II from active signal transmission. Deleting only the D1 extra loop does the reverse. Every such allele must be validated for surface expression equal to wild type, since a folding defect would masquerade as loss of signaling. Score proximal T cell receptor signaling by CD3 zeta and LCK phosphorylation, CD4 dependent responses to peptide MHC class II reagents, and exhaustion markers under sustained antigen.',
  'Lag3:humanized':
    'Relatlimab and the other clinical reagents do not recognize mouse LAG-3, so antibody work requires an ectodomain swap. Replace the exons encoding D1 through D4 and retain the mouse connecting peptide, transmembrane region, and cytoplasmic tail, so shedding by mouse ADAM proteases and FSAL-dependent signaling remain native and only the epitope changes. Verify that the human ectodomain still engages mouse MHC class II with useful affinity, because a humanized receptor unable to bind endogenous ligand blocks nothing and reads as a false negative. Fibrinogen like protein 1 cross-reactivity should be measured separately rather than assumed. Since clinical benefit is defined in combination, cross to a humanized Pdcd1 allele so dual blockade can be modelled honestly. Endpoints are exposure, receptor occupancy on tumor-infiltrating lymphocytes, CD8 polyfunctionality, and growth of syngeneic tumors with single-agent comparator arms.',
  'Havcr2:conditional-knockout':
    'TIM-3 does different jobs in different cells, so a floxed allele is the only way to assign a phenotype to a source. Flank the exon encoding the IgV domain, which removes phosphatidylserine, galectin 9 and CEACAM1 binding together, and leave the mucin stalk intact only if you confirm no membrane-anchored remnant still recruits Fyn. For the myeloid arm, Itgax-Cre addresses conventional dendritic cells and Lyz2-Cre the macrophage compartment, but neither is clean: Lyz2-Cre deletes poorly in dendritic cells while Itgax-Cre marks some macrophages and activated T cells, so pair them and confirm by sorting. Cx3cr1-CreER with tamoxifen suits microglia when neuroinflammation is the question, and E8I-Cre suits CD8-intrinsic exhaustion. Report deletion efficiency per sorted population, then read out cross-presentation and type I interferon for myeloid deletion, or tetramer-positive CD8 cytokine capacity and tumor burden for lymphoid deletion.',
  'Havcr2:knockout':
    'A germline null is easy to make and easy to overinterpret. Delete the coding exons spanning the IgV domain through the transmembrane segment so no soluble ectodomain remains to bind galectin 9. On C57BL/6 the null is viable with only modest enhancement of Th1 responses and no spontaneous autoimmunity, so single-mutant characterization looks negative unless the animals are challenged. The null is the closest genetic match to human loss-of-function variants, but mice do not reproduce the panniculitis-like lymphoma spontaneously, and additional pressure, either an inflammatory trigger or a second lesion, is generally needed before hemophagocytic features appear; treat that as an open question rather than an expectation. Practical endpoints are inflammatory cytokines including IL-1 beta and IL-18, ferritin and soluble CD25, splenic macrophage activation, and tumor rejection in compound crosses with Pdcd1.',
  'Havcr2:knockin':
    'Knockins test the unusual wiring of TIM-3 directly. Substituting phenylalanine for the cytoplasmic tyrosines prevents their phosphorylation, locking HLA-B associated transcript 3 onto the tail and blocking Fyn recruitment, which converts the receptor into a ligand-binding but signaling-dead protein and asks whether inhibition requires transmission or only occupancy. Mutating residues in the FG-CC\' cleft of the IgV domain abolishes phosphatidylserine and CEACAM1 binding while leaving the tail intact, the reciprocal experiment. Patient missense variants that destabilize IgV folding are also worth building, since they reduce surface protein rather than eliminating the gene and should behave as hypomorphs; confirm that by quantitative surface staining before drawing conclusions. Read out Fyn and p85 association by immunoprecipitation, apoptotic cell uptake for myeloid alleles, and cytokine polyfunctionality in antigen-specific CD8 cells.',
  'Havcr2:humanized':
    'Clinical anti-TIM-3 antibodies do not bind the mouse protein, so ectodomain replacement is required for pharmacology. Swap the exons encoding the IgV domain and mucin stalk while keeping the mouse transmembrane region and cytoplasmic tyrosines, so Fyn coupling and Bat3 release stay native and any antibody effect reflects epitope engagement rather than a rebuilt signaling module. Confirm the humanized receptor still binds mouse galectin 9 and phosphatidylserine, since a receptor blind to endogenous ligand makes blockade uninterpretable. Because expression extends to myeloid cells and to leukemic stem cells, Fc effector function is often the operative mechanism, so cross into human Fc gamma receptor mice before assigning activity to blockade alone. Combine with a humanized Pdcd1 allele given that measurable checkpoint phenotypes usually require dual targeting, and use exposure, occupancy, and tumor or leukemia burden as endpoints.',
  'Tigit:conditional-knockout':
    'Because TIGIT acts both cell-intrinsically and by shaping ligand availability for neighbors, compartment-restricted deletion is where the interesting answers sit. Flank the exon encoding the IgV domain so recombination removes CD155 and CD112 binding, and confirm that no truncated product reaches the surface. Foxp3-YFP-Cre tests the regulatory T cell arm, including IL-10 output and suppressive potency, and because Foxp3 is X-linked, restrict analysis to hemizygous males or account explicitly for mosaic females. E8I-Cre isolates CD8-intrinsic inhibition and Ncr1-Cre the NK arm, though its efficiency varies between NK subsets and must be measured rather than assumed. Cd4-CreERT2 with tamoxifen after priming distinguishes maintenance from induction. Score CD226 surface levels and dimerization state, CD155 density on tumor and stromal cells, IL-10 in sorted regulatory cells, and tumor growth with matched Cre-only controls.',
  'Tigit:knockout':
    'The germline null is viable with mild homeostatic changes, so its value is comparative rather than descriptive. Remove the full coding sequence rather than the ITIM alone, since a signaling-dead but ligand-binding protein would still sequester CD155 and produce a partial phenotype easily misread as residual inhibition. Expect compensation across the axis: CD226, CD96 and CD112R engage overlapping ligands, so measure their surface levels in the null before concluding a phenotype reflects loss of TIGIT alone, and plan compound alleles accordingly. Phenotypes emerge under challenge, particularly in implanted tumors and in combination with Pdcd1 deficiency, and they depend on tumor CD155 expression, so choose lines with defined ligand levels and report them. Endpoints worth collecting are tumor growth and rejection frequency, intratumoral regulatory to CD8 ratio, CD8 polyfunctionality, and NK cytotoxicity against CD155 high targets.',
  'Tigit:knockin':
    'Knockins are the sharpest tool here because TIGIT has two separable jobs. Substituting phenylalanine for the tyrosine in the ITT-like motif prevents Grb2 and beta-arrestin 2 recruitment and the downstream SHIP1 step, while an ITIM tyrosine substitution removes the other phosphorylation-dependent arm; building both singly and together shows which motif carries inhibitory output. The complementary allele mutates the ligand-contact surface of the IgV domain, so the receptor is expressed and can still signal if artificially engaged but cannot bind CD155, isolating ligand sequestration from CD226 as the mechanism. Match surface expression to wild type by flow cytometry for every allele, since reduced protein would confound the comparison. Read out CD226 homodimerization by crosslinking or proximity methods, proximal T cell receptor phosphorylation, regulatory cell IL-10, and tumor control, with the null as reference arm.',
  'Tigit:humanized':
    'Every clinical TIGIT antibody was raised against the human protein, so an ectodomain swap is mandatory for pharmacology. Replace the exon encoding the IgV domain and keep the mouse stalk, transmembrane segment, ITIM and ITT-like motif intact so inhibitory wiring is unchanged and only the epitope moves. Two checks matter before any efficacy run: that human TIGIT retains adequate binding to mouse CD155, otherwise blockade has nothing to block, and that apparent loss of activity does not simply reflect how mouse Fc gamma receptors handle human IgG1. Since Fc-mediated depletion of TIGIT high regulatory T cells is a leading mechanism, compare Fc-competent and Fc-silent versions of the same clone, and cross to human Fc gamma receptor mice for translational fidelity. Endpoints are occupancy, intratumoral regulatory cell depletion, CD8 to regulatory ratio, and tumor growth with and without PD-1 blockade.',
  'Pdcd1lg2:conditional-knockout':
    'Because PD-L2 is expressed by a few specific presenting populations rather than broadly, conditional deletion is the only way to attribute a phenotype to a source. Flank the exon encoding the IgV domain so recombination abolishes PD-1 engagement; note that RGMB binding maps to the same ectodomain, so this allele will not separate the two ligand functions. Itgax-Cre covers conventional dendritic cells, Lyz2-Cre the macrophage compartment including the lung interstitial macrophages relevant to the RGMB axis, and Cd19-Cre or Aicda-Cre the germinal center B cell arm, with Aicda-Cre restricting loss to cells that have already been activated. Since IL-4 and STAT6 drive expression, sensitize with house dust mite or ovalbumin before scoring, or the protein will be near absent at baseline. Endpoints are airway hyperresponsiveness and eosinophilia, follicular helper and germinal center output, and antigen-specific CD8 expansion.',
  'Pdcd1lg2:knockout':
    'The single null is viable and usually silent, which is the main design fact to plan around. Delete the exons encoding the IgV and IgC2 domains so no soluble ectodomain remains to act as a decoy for PD-1. The important practical point is linkage: Cd274 sits immediately adjacent to Pdcd1lg2 on mouse chromosome 19, so a double-deficient animal cannot be produced by simply intercrossing two independently targeted lines, because the required cis configuration depends on a rare recombination between tightly linked loci. Target both genes in the same zygote instead, or screen intensively for the recombinant chromosome and confirm it by long-range PCR. Baseline immunophenotyping will be unremarkable, so plan challenge: allergic airway inflammation, chronic viral infection, and syngeneic tumor rejection, using response to PD-1 blockade as a functional measure of remaining ligand supply.',
  'Pdcd1lg2:knockin':
    'Two knockin designs justify the effort. First, a reporter inserted at the locus, either a fluorescent protein behind an internal ribosome entry site or a self-cleaving peptide, resolves which cells actually express PD-L2 and when, which matters because expression is IL-4 and STAT6 dependent and therefore nearly invisible at baseline; adding a tamoxifen-inducible Cre to the same cassette converts it into a fate-mapping and deletion tool for PD-L2 positive cells. Second, point substitutions separating the PD-1 contact surface from the RGMB contact surface within the ectodomain answer what the conditional allele cannot, namely whether lung tolerance reflects PD-1 signaling or the macrophage RGMB axis. Verify equal surface expression for mutant alleles, then read out PD-1 fusion protein binding, RGMB coprecipitation, and airway inflammation with type 2 cytokine profiling.',
  'Pdcd1lg2:humanized':
    'Humanizing this locus is a specificity tool more than an efficacy tool, since few clinical programs target PD-L2 directly. Replace the exons encoding the IgV and IgC2 domains with human sequence, keeping the mouse transmembrane and cytoplasmic regions so trafficking and turnover are unchanged. The usual reason to build it is to test whether a PD-1 directed antibody or a PD-L1 targeted agent unexpectedly engages the second ligand, or to make PD-1 fusion reagents behave as they would in patients. Because human PD-L2 and mouse PD-1 do not necessarily pair with useful affinity, cross to a humanized Pdcd1 allele so receptor and ligand match, then confirm the interaction by surface binding before committing to efficacy studies. Endpoints are ligand occupancy on dendritic cells and macrophages, PD-1 pathway activity in antigen-specific CD8 cells, and tumor growth against single-humanization controls.',
  'App:conditional-knockout':
    'App nulls survive, so the case for a floxed allele rests on redundancy and timing rather than lethality. The real application is conditional App deletion on an Aplp2 null background, because that combination is perinatal lethal in the germline and only tissue-restricted removal makes adult analysis possible. Flank the exons encoding the E1 and E2 modules together with the transmembrane region so no signaling-competent stub remains. Neurod6-Cre or Camk2a-Cre restrict loss to forebrain excitatory neurons for synaptic questions, Cx3cr1-CreER addresses microglial App, and a cholinergic motor neuron driver is needed if the neuromuscular defect seen in compound nulls is the endpoint. Inducible drivers separate developmental from maintenance roles, which matters because APP contributes to axon outgrowth. Score spine density, field potentiation and paired-pulse behavior, neuromuscular junction morphology and quantal content, and secreted APP alpha in the deleted tissue.',
  'App:knockout':
    'A null tells you what APP does, not what amyloid does, and the two are routinely confused. Germline deletion is viable with reduced body weight, subtle gliosis, impaired long-term potentiation, and a lowered seizure threshold, phenotypes muted because Aplp1 and Aplp2 carry overlapping functions. Because deleting the gene removes the Abeta source entirely, this allele cannot model Alzheimer pathology; it is a loss-of-function and specificity resource. Its best uses are as an absolute negative control for anti-APP and anti-Abeta antibodies, for BACE1 and gamma-secretase substrate specificity work, and as the base for compound crosses with Aplp1 or a conditional Aplp2 allele. Delete the entire coding region so no secreted fragment remains, since soluble APP alpha is itself bioactive. Endpoints are fragment-level protein confirmation, hippocampal electrophysiology, grip and rotarod performance, and Aplp1 and Aplp2 compensation measured directly.',
  'App:knockin':
    'Point mutation knockins at the endogenous locus made overexpression models obsolete, but they only work in combination. Swedish KM670/671NL raises beta-secretase cleavage, substitutions near the gamma-secretase site shift the Abeta42 to Abeta40 ratio, and Arctic E22G accelerates protofibril formation; stacking them compresses the timeline into a usable window. None of this yields deposition unless the Abeta-coding sequence is human, so mutation knockins must be built on humanized Abeta exons rather than mouse sequence. Be explicit about what the Arctic allele costs: it alters the aggregate species itself, so conformation-dependent antibodies and imaging ligands may not read it faithfully. The protective A673T substitution is the useful reciprocal allele. Endpoints are Abeta40 and Abeta42 by immunoassay, plaque load and cerebral amyloid angiopathy, microglial and astrocytic responses, and only then behavior.',
  'App:humanized':
    'Humanizing the Abeta-coding exons in place is the minimal edit that makes mouse APP relevant, and precision matters more than scope. The three rodent-specific substitutions lie within the region encoded by the exons spanning the Abeta sequence, so replacing that short stretch with human codons restores aggregation-competent peptide while leaving the endogenous promoter, copy number, and splicing of the APP695, APP751 and APP770 isoforms untouched. That avoids the fragment overproduction and insertional artifacts of transgenic overexpression. The limitation is plain: humanized Abeta alone deposits poorly within a mouse lifespan, so this allele is a platform for familial mutation stacking or for antibody and BACE1 inhibitor pharmacology, not a standalone pathology model. Endpoints are human-sequence Abeta40 and Abeta42 in brain and plasma, engagement by clinical antibodies that do not bind rodent Abeta, and unchanged total APP levels.',
  'Psen1:conditional-knockout':
    'Adult brain work on this locus has no alternative, since constitutive nulls never reach weaning. Flank the exons encoding the TM6 and TM7 region so excision removes the catalytic aspartates outright rather than leaving a truncated subunit that still nucleates a complex with nicastrin. CaMKIIalpha-Cre or Nex-Cre restrict loss to postnatal forebrain excitatory neurons and avoid the somite failure that early drivers reintroduce; Nestin-Cre acts embryonically and recreates the Notch phenotype you were trying to bypass. Expect an incomplete answer from the single conditional, because Psen2 sustains residual cleavage, so breed onto a Psen2 null background when total gamma-secretase output is the endpoint. Read APP C83 and C99 accumulation by immunoblot, Notch intracellular domain and Hes5 for substrate specificity, and cortical thickness with age. Confirm excision by PCR on sorted neurons rather than bulk cortex.',
  'Psen1:knockout':
    'A germline null is an embryonic Notch experiment, not an Alzheimer experiment. Homozygotes die perinatally with disorganized somites, axial skeletal malformation, and cranial hemorrhage, a phenotype similar in kind to Dll1 or Rbpj loss, which fixes the useful analysis window at roughly E9.5 to E14.5. Build the allele by removing the promoter and first coding exon so no amino-terminal fragment survives, since a frameshift alone risks a stable truncation. Heterozygotes are unremarkable, so the allele reports requirement rather than dosage. Durable value lies in derived fibroblasts: single null and Psen1 with Psen2 double null lines are the standard reconstitution platform for asking whether a mutant subunit supports endoproteolysis and substrate cleavage in vitro. Score somite number, cleared skeletal preparations, Hes5 in situ signal, and C99 accumulation in the derived lines.',
  'Psen1:knockin':
    'Patient missense knockins hold expression under endogenous control, which matters because presenilin assembles stoichiometrically and overexpression distorts complex composition. M146V, L166P, and the exon 9 deletion allele reduce processivity by different amounts, so pick the one whose amyloid beta 42 to 40 shift matches the effect size you need. Introduce a single codon change with a silent restriction site for genotyping and excise any selection cassette, since retained intronic neo depresses transcription. The binding constraint is substrate: murine amyloid beta differs from human at three residues and aggregates poorly, so this knockin alone gives a ratio shift with no plaque. Cross to a humanized amyloid beta App knockin before scoring deposition. Quantify peptide species by mass spectrometry rather than ELISA alone, and examine axial skeleton and thymocyte development in homozygotes for partial Notch loss.',
  'Psen1:humanized':
    'Be skeptical here. Mouse and human presenilin 1 are roughly ninety percent identical across the catalytic core, process the same substrates, and gamma-secretase modulators engage the complex and its substrate rather than a species-divergent surface, so swapping the coding sequence rarely changes compound pharmacology. What genuinely differs is the substrate, making humanization of the amyloid beta region of App the higher-yield edit for modulator or inhibitor testing. Humanizing this locus is justified when a therapeutic reads the human transcript directly, as an oligonucleotide does, or when an antibody epitope is human-restricted. If you build it, replace coding exons while retaining mouse introns and regulatory sequence so splicing around exons 8 and 9 and expression level are preserved. Verify endoproteolysis into amino-terminal and carboxy-terminal fragments and co-immunoprecipitation with nicastrin and PEN2 before phenotyping.',
  'Psen2:conditional-knockout':
    'A conditional at this locus is nearly silent alone, because Psen1 carries most cleavage in almost every tissue examined. Design it as half of a compound strategy, floxing the exons encoding the catalytic core and combining with a Psen1 conditional; the two genes sit on different mouse chromosomes, so budget the breeding and cohort mathematics accordingly. Where the allele earns its place by itself is compartment-specific biology, since these complexes concentrate in late endosomes and lysosomes. Cx3cr1-CreERT2 for microglial phagosome maturation or Sftpc-CreERT2 for alveolar epithelium addresses questions Psen1 deletion cannot. Tamoxifen timing matters in lung, where the fibrotic phenotype is age dependent. Read endolysosomal pH and cathepsin maturation, calcium transfer at endoplasmic reticulum to mitochondria contacts, and C99 and Notch intracellular domain levels, always quantifying Psen1 transcript for compensation.',
  'Psen2:knockout':
    'Unlike its paralog, this gene tolerates constitutive deletion, so the simple null is the correct first allele rather than a conditional. Homozygotes survive to old age with breeding intact and slowly progressive lung fibrosis as the only spontaneous finding, so adults can be phenotyped directly and the null doubles as a sensitizing background for Psen1 conditionals. Remove the exons encoding the aspartate-bearing transmembrane segments so no catalytically competent fragment persists. Use the line to isolate compartment-specific rather than shared functions: lysosomal proteolysis and autophagic flux, calcium exchange at mitochondria-associated membranes, and the endosomal amyloid beta pool measured by interstitial fluid microdialysis. Two cautions govern interpretation. Psen1 transcript frequently rises after deletion, so quantify it before calling any phenotype specific, and remember that double nulls with Psen1 die embryonically from Notch failure, capping total-loss ambitions.',
  'Psen2:knockin':
    'N141I sits in the second transmembrane segment and lowers processivity, raising the proportion of longer amyloid beta peptides without abolishing catalysis, which is why a single codon knockin at the endogenous locus is the honest instrument. Homozygotes are tolerated, unlike aggressive Psen1 alleles, so gene dosage can be compared directly. Add a silent restriction site for genotyping and excise residual selection cassettes from the intron. Because murine amyloid beta aggregates poorly, cross into a humanized amyloid beta App knockin before expecting deposition; on mouse substrate the readout is peptide ratio only. Beyond amyloid, this substitution enhances inositol trisphosphate receptor mediated calcium release, so include store release measurements and lysosomal function alongside peptide profiling. Run a Psen1 M146V knockin in parallel to separate paralog-specific consequences from generic loss of processivity.',
  'Psen2:humanized':
    'Coding sequence is highly conserved between species here, and the assembled complex, not a divergent surface, is what small molecule modulators engage, so humanization buys little pharmacological fidelity. The defensible reasons are narrow: matching oligonucleotide target sequence, supplying human-restricted antibody epitopes, or supporting patient variant panels in human context. If the question is amyloid beta length distribution under modulator treatment, humanize the App substrate instead. When building the allele, retain mouse promoter, untranslated regions, and introns so that the endosomal and lysosomal targeting determined by the amino-terminal region and native expression level survive the swap; forcing high expression relocalizes complexes to the plasma membrane and destroys the compartment biology that distinguishes this paralog. Validate by subcellular fractionation showing late endosomal enrichment, co-immunoprecipitation with nicastrin, and species-specific quantitative PCR before dosing any transcript-directed agent.',
  'Mapt:conditional-knockout':
    'Because the germline null is healthy, a conditional here buys temporal and cellular resolution rather than viability. Two questions justify it: whether tau is required to maintain circuits that already formed, and whether sustained lowering in a defined cell type is tolerated, the mouse surrogate for oligonucleotide safety. Choose the floxed interval carefully. Removing only the repeat-encoding exons leaves a projection-domain fragment that can sequester kinases and act as a partial dominant, so flank the promoter and first coding exon for clean loss. Slc17a7-Cre or CaMKIIalpha-Cre serve cortical excitatory neurons, Chat-Cre serves motor neurons, and a tamoxifen-inducible driver is required when adult onset is the point. Phenotypes usually need provocation, so score axonal transport, microtubule dynamics, kainate seizure threshold, and excitotoxic vulnerability rather than baseline behavior alone.',
  'Mapt:knockout':
    'The most valuable thing this null does is subtract. Endogenous murine four-repeat tau co-assembles with human tau and dilutes filament composition, so the null is the standard host chassis for human knockins, humanized loci, and seeding studies where filament content must be unambiguous. As a phenotype-generating allele it is modest: homozygotes are viable and fertile, Map1a rises to compensate, and deficits appear mainly with age or challenge, including muscle weakness and altered excitotoxic vulnerability. Delete the promoter and first coding exon rather than internal exons, and check neighboring transcription, since the locus carries antisense and overlapping transcripts. Validate by immunoblot with pan-tau and isoform-specific antibodies confirming no residual four-repeat signal, quantify Map1a and Map2 compensation, then treat behavioral endpoints as challenge dependent rather than constitutive.',
  'Mapt:knockin':
    'State the limitation first. Adult mouse brain makes almost exclusively four-repeat tau and murine tau aggregates poorly, so a coding mutation placed in the mouse locus yields weaker pathology than the same change in human sequence. P301 lies within the first microtubule-binding repeat encoded by the alternatively spliced exon, so a mouse-locus knockin does put the substitution in correct structural context, but expect long latency and low filament burden at endogenous dosage. Intronic and exonic splice-shifting FTDP-17 mutations cannot be modeled here at all, because the isoform ratio they perturb does not exist in adult mouse brain. If filament formation and antibody or oligonucleotide response are the goal, place the mutation in a humanized allele instead. Endpoints: sarkosyl-insoluble tau, conformational and phospho-epitope staining, Gallyas silver, and seeding activity in a biosensor assay.',
  'Mapt:humanized':
    'This is the allele the gene actually demands. Replacing the mouse locus with the human genomic region, promoter through three prime untranslated region, reconstitutes exon 2, exon 3, and exon 10 splicing, so animals develop the mixed three-repeat and four-repeat isoform profile that mouse sequence cannot generate. That single feature unlocks splice-shifting FTDP-17 mutations, haplotype comparisons, human-restricted antibody epitopes, and oligonucleotide target sites. Build it on a null background so murine tau does not compete for filament incorporation. Two execution points matter. Isoform balance emerges across postnatal development rather than at birth, so age animals before sampling, and expression must be benchmarked against human brain by immunoblot and quantitative PCR, since genomic replacements often under-express. Score exon 10 inclusion by reverse transcription PCR, oligonucleotide target engagement, cerebrospinal fluid tau, and seeding competence after challenge.',
  'Snca:conditional-knockout':
    'Viability of the null means this allele concerns timing and cell identity, not survival. The productive use is adult-onset deletion in dopaminergic neurons, asking whether the protein is required to maintain terminals that already exist, which is the safety question behind synuclein lowering. Slc6a3-CreERT2 gives clean dopaminergic restriction; Th-Cre is widely available but shows ectopic and variable activity, so validate with a reporter before committing a cohort. Flank the exon carrying the start codon rather than only the segment encoding the hydrophobic aggregation-prone core, since a truncated product retaining the amphipathic repeats still binds membranes. Two breeding cautions: exclude substrains carrying the spontaneous locus deletion to avoid confounded genotypes, and be prepared to add Sncb alleles, because paralog compensation is real. Read dopamine release by voltammetry, vesicle pools by electron microscopy, and SNARE assembly.',
  'Snca:knockout':
    'A constitutive null is straightforward and unusually useful here, because a spontaneous deletion of this locus already exists in one widely used substrain, giving both a natural null and a standing caution about background genotype. Phenotypes are mild: modest reduction in striatal dopamine, altered vesicle recycling under sustained stimulation, and resistance to certain neurotoxins. The strongest applications are negative ones. Nulls resist pathology after inoculation with preformed fibrils, the definitive control establishing that seeding requires endogenous substrate, and the null serves as clean host for humanized or copy-number alleles. When designing the deletion, remove coding exons while leaving the immediately adjacent gene intact, since the spontaneous substrain deletion removes both and that confound has misled published work. Score voltammetric release, vesicle counts by electron microscopy, and fibril challenge resistance rather than baseline behavior.',
  'Snca:knockin':
    'One fact constrains this allele: murine protein already carries threonine at the position where the familial human substitution places it, so installing A53T in the mouse locus creates no change and no model. E46K and A30P remain informative on murine sequence because those positions differ, and E46K in particular deepens the membrane-binding repeat defect that drives assembly. More productive mouse-locus knockins interrogate regulation rather than familial genetics: serine 129 replaced by alanine or by a phosphomimetic separates phosphorylation from aggregation, and repeat-motif substitutions test the membrane-binding requirement directly. Dosage knockins adding functional copies model the duplication and triplication genetics faithfully. Endpoints: phosphoserine 129 immunostaining, proteinase K resistant inclusions, sequential detergent extraction, seed amplification assays, and voltammetric dopamine release. For anything needing human epitopes or fibril strain fidelity, humanize the coding sequence instead.',
  'Snca:humanized':
    'Humanization is the default for this gene, not an optional refinement. Mouse and human protein differ at several residues, including the position carrying the familial threonine substitution in patients, and those differences change fibril strain behavior, antibody epitope recognition, and oligonucleotide target sequence. Replace the mouse coding region with human sequence while retaining mouse regulatory elements so presynaptic expression stays physiologic, or install a human genomic segment when copy number is the variable under study. Expect no spontaneous pathology within a normal lifespan from humanization alone, so plan a second input: preformed fibril inoculation, added gene copies, or a familial mutation in cis. Build on a null background so murine protein does not contaminate filaments. Endpoints: validation of human-specific antibodies, transcript and protein knockdown after oligonucleotide dosing, phosphoserine 129 spread mapping, and dopaminergic terminal integrity.',
  'Htt:conditional-knockout':
    'There is no substitute, since homozygous null embryos fail before somitogenesis. Two distinct experiments justify the allele. Deletion after development tests whether huntingtin is required for maintenance, the direct surrogate for non-selective lowering safety; excising a floxed exon 1 from an expanded knockin instead tests reversibility of established pathology. Match driver to region: Drd1-Cre and Adora2a-Cre separate direct and indirect pathway medium spiny neurons, Emx1-Cre or CaMKIIalpha-Cre cover cortex, Slc6a3-CreERT2 addresses dopaminergic input, and Alb-Cre answers hepatic safety. Nestin-Cre gives broad but mosaic embryonic deletion, and high Cre expression is itself toxic to striatal neurons, so include Cre-only controls. Score DARPP-32 and enkephalin in striatum, brain-derived neurotrophic factor transcript, cytoplasmic versus nuclear REST, autophagy markers, clasping and rotarod, and verify excision in sorted nuclei.',
  'Htt:knockout':
    'The straight null answers only two things, and it is worth knowing which. Homozygotes arrest near gastrulation with defective extraembryonic and streak development, so the allele defines absolute requirement and supplies embryos and derived lines for cell-autonomous biochemistry, nothing more. The heterozygote is the underused half. Because most lowering strategies reduce wild-type along with mutant transcript, a lifelong fifty percent reduction is the cleanest available test of tolerability, so hemizygotes should be aged and phenotyped rather than merely genotyped. Construct the null by removing the promoter and first coding exon so no amino-terminal fragment persists; a graded hypomorphic series is more informative than a flat deletion when partial function is the question. Endpoints: embryo morphology at E7.5 through E8.5, then striatal volume, DARPP-32, neurotrophin transcript, and motor testing in heterozygotes.',
  'Htt:knockin':
    'Expansion at the endogenous locus is the reference design here, and the decisions that matter are repeat length and exon 1 sequence context. Use a humanized exon 1 so the polyglutamine tract sits in correct polyproline context and the aberrantly spliced short transcript, which carries much of the toxicity, is produced as in patients. Longer tracts compress the timeline but distort instability behavior, so choose length against endpoint rather than convenience. Colony management is the real burden: tract size drifts between generations with a paternal expansion bias, so size every breeder by fragment analysis and report measured length, not founder value. Endpoints: somatic instability index comparing striatum against cerebellum, aggregate detection with amino-terminal antibodies, aberrant exon 1 transcript by reverse transcription PCR, transcriptional dysregulation signature, and progressive DARPP-32 loss.',
  'Htt:humanized':
    'Humanization serves sequence-dependent therapeutics rather than biology, since mouse and human huntingtin are close functional equivalents. Antisense oligonucleotides, small interfering RNAs, and allele-selective approaches keyed to single nucleotide polymorphisms in linkage with the expansion all require human target sequence to be present, and none can be tested on murine transcript. Decide scope by mechanism: humanizing exon 1 with flanking intron covers the toxic fragment and the commonest target region, while full locus replacement becomes necessary when target sites lie in distal introns or the three prime untranslated region. Configure animals with one humanized mutant allele over one mouse wild-type allele to mimic patient genotype and measure allele selectivity honestly. Confirm functional equivalence first: homozygous humanized animals must be viable, demonstrating that the replacement rescues the lethal null.',
  'Sod1:conditional-knockout':
    'Be clear about what this allele can address. Loss of dismutase activity is not the ALS mechanism, so a conditional null is an oxidative-stress and tissue-autonomy tool, not a disease model. Its best use is asking which cell type generates a given deficit seen in the null: Chat-Cre or Mnx1-Cre for motor neurons, Aldh1l1-CreERT2 for astrocytes, Mck-Cre or a skeletal actin driver for muscle, where restricted deletion suffices for atrophy, and Mpz-Cre for Schwann cells. The gene is small, so flanking the entire coding region is simpler and safer than excising internal exons that might leave a metal-binding fragment. One pitfall dominates: the protein is abundant and long lived, so activity persists for weeks after recombination. Confirm loss by in-gel dismutase assay, then score junction innervation, distal axon integrity, aconitase activity, and auditory brainstem thresholds.',
  'Sod1:knockout':
    'The single most useful fact about this allele is a negative result. Homozygous nulls are viable and never develop motor neuron disease, the load-bearing evidence that patient mutations act by toxic gain of function rather than by enzymatic insufficiency, so any project proposing this line as an ALS model has made a category error. What the null does deliver is oxidative-stress biology: age-dependent muscle atrophy, cochlear hair cell loss with rising auditory thresholds, reduced female fertility, and markedly impaired axon regeneration after nerve injury. Delete the coding exons entirely, confirm absence of activity by in-gel assay rather than transcript alone, then verify Sod2 and Sod3 are unchanged before attributing anything to compensation. Strain background modifies every oxidative endpoint, so fix and report it. Score dismutase activity, protein carbonyls, isoprostanes, grip strength, junction fragmentation, and auditory thresholds.',
  'Sod1:knockin':
    'Endogenous-locus missense knockins solve the dosage problem high-copy transgenics create, at the cost of speed. Say so up front: a single-copy patient mutation typically produces slow, subtle, or aged-onset disease rather than the aggressive course of overexpressing lines, so power studies for long timelines or plan a second insult. Choose the mutation for the mechanism being separated. G85R is dismutase inactive and therefore dissociates toxicity from enzymatic activity, A4V destabilizes the dimer interface, and D90A is recessive in patients, making it the right tool for testing modifier dependence. Introduce a single codon change with a silent genotyping site, and consider humanizing the coding sequence in cis so oligonucleotide target sites exist. Endpoints: conformation-specific misfolded protein staining, detergent-insoluble and disulfide-crosslinked species, junction occupancy, compound muscle action potential amplitude, and survival only in aged cohorts.',
  'Sod1:humanized':
    'Sequence identity between species is only about eighty-four percent, and the divergent positions matter twice: they alter aggregation behavior, and they mean oligonucleotide and small interfering RNA target sites present in human transcript are absent from the mouse gene. Any program testing a transcript-directed therapeutic needs human sequence at the endogenous locus, and testing such agents against murine transcript is not an approximation but an invalid experiment. Replace the coding exons with human sequence under mouse regulatory control when physiologic expression is wanted, extending into the three prime untranslated region when target sites lie there. Place a patient mutation in cis when the goal is treating disease rather than measuring knockdown. Validate functional replacement first by showing the humanized allele corrects null phenotypes on activity gel and auditory testing, then measure knockdown in central nervous system and cerebrospinal fluid.',
  'Apoe:conditional-knockout':
    'Because ApoE is secreted and exchanges between lipoprotein particles, a floxed allele only answers questions where the local source dominates. Hepatocytes supply most plasma ApoE, so Alb-Cre deletion recreates remnant accumulation while leaving macrophage ApoE intact, and LysM-Cre or Cx3cr1-CreER deletion isolates the lesional macrophage pool that modifies plaque composition without changing plasma cholesterol much. The CNS pool is locally made by astrocytes and does not equilibrate with plasma, which makes Aldh1l1-CreERT2 or Gfap-Cre the informative drivers for amyloid work; verify that the Gfap line is not recombining in neurons or in liver. Flank exons 2 through 4 so both the receptor-binding four-helix bundle and the carboxy-terminal lipid-binding region are removed rather than producing a truncated secreted fragment. Read out regional brain ApoE by ELISA on sorted cells, plasma lipoprotein FPLC, and en face lesion area.',
  'Apoe:knockout':
    'A whole-locus null remains the most productive single allele here, but be clear about what it models. Hypercholesterolemia in these mice is driven by failure of remnant and VLDL clearance rather than LDL excess, so lesion composition and lipoprotein distribution differ from familial hypercholesterolemia, where an Ldlr null is the better comparator. Delete all four exons rather than interrupting exon 3, since truncated amino-terminal fragments retain some receptor binding and complicate interpretation. Keep the line congenic on C57BL/6 because atherosclerosis susceptibility is strongly strain dependent, and decide up front whether chow-fed spontaneous lesions or Western diet acceleration fits the timeline. When using the null as a sensitized background for a second gene, run a lipid-matched control, since many downstream phenotypes track plasma cholesterol rather than ApoE itself. Score en face aortic lesion area, aortic root sections, FPLC profiles, and hippocampal synaptic markers.',
  'Apoe:knockin':
    'Point substitution at the endogenous locus is the way to test mechanism without changing expression level, and mouse Apoe is unusually amenable because a single threonine to arginine change at the position corresponding to human residue 61 installs the domain interaction that distinguishes APOE4 behavior, giving a mouse-sequence allele that separates domain interaction from the rest of the isoform difference. Receptor-binding-dead substitutions in the basic cluster of helix 4 uncouple LDLR and LRP1 engagement from lipid binding, while alanine replacement of the heparin-binding basic residues isolates proteoglycan-dependent uptake. Keep the 3-prime untranslated region and the hepatic control region intact, since deleting downstream enhancers silences hepatic expression and produces an unintended hypomorph. Add a small carboxy-terminal tag only after confirming it does not impair self-association. Confirm by plasma ApoE mass, lipoprotein distribution across FPLC fractions, receptor-binding assays on isolated particles, and lesion progression.',
  'Apoe:humanized':
    'This is the one design that cannot be substituted, because mouse ApoE has no isoform series and its own sequence behaves like APOE4 at the domain interaction level. Replace the mouse coding exons with human APOE2, APOE3 or APOE4 sequence while retaining the mouse promoter and the downstream hepatic control region, which keeps expression near physiological and avoids the artifacts of transgenic overexpression. If the goal is testing antisense oligonucleotides, siRNA or isoform-selective antibodies, humanize genomically so that intronic and untranslated target sequence is human as well. Match all three lines on one background and verify equal ApoE mass by isoform-blind ELISA before comparing phenotypes, since apparent isoform effects often reflect expression differences. Expect type III-like hyperlipidemia in APOE2 homozygotes. Read out lipidation state on native gels, and in amyloid crosses score plaque burden, soluble amyloid beta clearance kinetics, and plaque-associated microglial state.',
  'Tardbp:conditional-knockout':
    'Because germline nulls fail around implantation, a floxed allele is the only route to adult loss of function. Flank the exon carrying the initiator codon plus the second coding exon so that recombination removes both RRM domains and cannot yield an amino-terminally truncated product that still dimerizes. Choose drivers by circuit: Chat-Cre or Mnx1-Cre for spinal motor neurons, Camk2a-CreERT2 for forebrain excitatory neurons to model frontotemporal degeneration, Cx3cr1-CreER for microglial contribution, and Myf5 or Acta1 drivers if muscle-intrinsic effects are in question. Deletion is rapidly lethal to neurons, so tamoxifen dosing and time to harvest must be titrated rather than fixed. Autoregulation complicates mosaic tissue because unrecombined cells raise TDP-43 levels, which means quantification must be single-cell. Score nuclear TDP-43 loss by immunostaining, mouse-validated cryptic exon inclusion by RNA sequencing, neuromuscular junction denervation, and grip strength.',
  'Tardbp:knockout':
    'A constitutive null has limited standalone value here: homozygotes die around implantation, and heterozygotes are close to normal because TDP-43 clamps its own abundance through 3-prime untranslated region binding, so protein rarely falls to half. That autoregulation makes the null a poor sensitizing background. Its real uses are genetic: place a patient missense or nuclear localization signal knockin over the null to remove the wild-type allele and ask whether the mutant supports viability and function, which distinguishes gain of function from haploinsufficiency more cleanly than homozygosing a knockin. Nulls also anchor antibody and reagent validation and provide null embryonic stem cells for chimera and complementation work. Delete the entire coding region rather than inserting a cassette into one exon, since cassette alleles frequently leak. Measure protein by quantitative western on tissue lysates, not transcript alone, and record embryonic lethality timing precisely.',
  'Tardbp:knockin':
    'Knockin at the endogenous locus is the preferred design for this gene because transgenic overexpression is toxic on its own and because the 3-prime untranslated region autoregulatory loop must stay intact for expression to remain physiological. Useful targets fall into three groups: low complexity domain missense changes of the M337V, A315T and Q331K class, which shift phase behavior and aggregation propensity; substitutions in the bipartite nuclear localization signal, which drive cytoplasmic accumulation and simultaneously relieve autoregulation, so watch total protein rise; and RRM1 lysine to glutamine acetylation mimics or carboxy-terminal serine to aspartate phospho-mimetics that test post-translational control of solubility. Introduce changes without leaving a selection cassette or a residual intronic FRT scar near splice sites. Interpret with fractionation into soluble and urea pools, phospho-TDP-43 immunostaining, nuclear to cytoplasmic ratio per cell, splicing changes by RNA sequencing, and motor endpoints.',
  'Tardbp:humanized':
    'Be clear about what humanization buys. TDP-43 protein is roughly ninety-six percent identical between mouse and human, so swapping coding sequence rarely changes protein behavior. The genuine indications are pharmacological and epitope-driven: a humanized transcript provides authentic sequence for antisense oligonucleotide and siRNA screens, for degrader or stabilizer campaigns, and for antibodies raised against human phospho-epitopes. The commonly cited motivation, human cryptic exon readouts, is not solved by humanizing this gene. The cryptic exons in STMN2 and UNC13A sit in primate-specific intronic sequence, so those loci must be humanized instead, and the two edits are complementary rather than interchangeable. If genomic humanization is chosen, retain the endogenous autoregulatory 3-prime untranslated region or accept an expression shift. Validate by allele-specific sequencing of the transcript, quantitative protein levels against wild type, splicing profile comparison, and confirmation that oligonucleotide knockdown behaves as it does in human cells.',
  'Fus:conditional-knockout':
    'A floxed allele is needed because constitutive nulls die perinatally on C57BL/6, but the more important reason to build it is to test the loss of function hypothesis directly, and the answer so far is sobering: deleting Fus in spinal motor neurons with Chat-Cre or Mnx1-Cre is largely tolerated, which pushes causality toward cytoplasmic gain of function. Use the allele instead for nuclear loss questions relevant to frontotemporal degeneration, with Camk2a-CreERT2 or Nes-Cre, and for hematopoietic phenotypes with Vav1-Cre, since nulls show B lymphocyte defects. Flank the exons encoding the RRM through zinc finger so the product cannot retain RNA binding, and note that FUS autoregulates through retention of its own introns, so partial alleles behave unpredictably. Interpret with Mapt exon 10 splicing, intron retention signatures, neuromuscular junction morphology, and paralog levels for Ewsr1 and Taf15.',
  'Fus:knockout':
    'The constitutive null is informative mainly as a boundary condition. Homozygotes die within hours of birth on C57BL/6 while surviving at low frequency on outbred backgrounds with sterility, radiation sensitivity and dendritic spine abnormalities, so any phenotype reported from a null must state the background or it cannot be compared. Heterozygotes are essentially normal and do not develop motor degeneration, which is the strongest single argument that patient alleles act by gain of function rather than haploinsufficiency, and that inference depends on having the clean null in hand. The other use is complementation: cross a truncation or NLS-mutant knockin onto the null to test whether the mutant protein supports viability without any wild-type FUS. Delete the whole coding region to avoid producing an autoregulation-evading fragment. Score neonatal survival by background, male fertility, B cell maturation, chromosome aberrations in fibroblasts, and hippocampal spine density.',
  'Fus:knockin':
    'This is the design that reproduces motor neuron loss at endogenous expression. Target the PY nuclear localization signal, using the arginine and proline positions in mouse Fus that correspond to human R521 and P525 rather than assuming the human numbers apply, since the mouse protein is shorter and residue positions shift. Frameshift alleles that truncate the final exon and delete the signal outright give the most severe cytoplasmic redistribution and are usually studied as heterozygotes, because homozygotes are poorly viable. Arginine methylation in the adjacent RGG region tunes Transportin-1 binding, so methylation-site substitutions provide a graded series rather than an on or off allele. Avoid tags at the carboxy terminus, which sit inside the import signal. Endpoints that matter are nuclear to cytoplasmic FUS ratio per motor neuron, stress granule partitioning, insoluble fraction accumulation with age, neuromuscular junction denervation, and rotarod or grip decline against littermates.',
  'Fus:humanized':
    'Humanization has a concrete justification here that it lacks for many RNA-binding proteins. Mouse FUS is shorter than the human protein and the carboxy-terminal region diverges, so patient residue numbering does not transfer and each variant has to be re-mapped. Replacing the locus with human genomic sequence, or at minimum the final exons plus flanking intron, lets variants be installed with their clinical designations and preserves the human intron retention element that autoregulates transcript abundance. The stronger driver is therapeutic: antisense oligonucleotides and siRNAs directed against human FUS require authentic target sequence, including untranslated regions, and cannot be tested on the mouse gene. The gene is compact enough that full genomic replacement is practical. Before use, confirm transcript and protein levels match wild type, since a humanized allele that overexpresses will aggregate for the wrong reason, then score mislocalization, insolubility, and motor performance.',
  'Lepr:conditional-knockout':
    'Cell-type-restricted deletion is where this locus pays off, because leptin action is distributed across neuronal populations with opposing outputs. Flank the exon encoding the long-form intracellular tail so recombination removes Box1 and Box2 while leaving the short isoforms and the extracellular domain intact, which keeps leptin transport and binding capacity unchanged. Pair with Agrp-IRES-Cre and Pomc-Cre to separate orexigenic from anorexigenic contributions, Slc32a1-Cre or Slc17a6-Cre for broader neurotransmitter classes, Sf1-Cre for ventromedial hypothalamus, and Alb-Cre or Ins1-Cre for peripheral tissues. Avoid Ins2 promoter Cre lines, which recombine in hypothalamus and have produced years of ambiguous beta-cell data. Pomc-Cre also acts embryonically and marks progenitors that become Agrp neurons, so confirm the recombined population by reporter. The inverted transcription-blocked allele is the complement, restoring receptor in single populations. Read body weight, intake, EchoMRI composition, arcuate phospho-STAT3, and clamped hepatic glucose output.',
  'Lepr:knockout':
    'An engineered whole-locus null is not equivalent to the classic db allele, and the difference matters. The db mutation is a splice defect that abolishes only the signaling isoform, leaving short receptor forms available for leptin transport and clearance, whereas deleting the locus removes those too, which raises circulating leptin further and eliminates any short-form-dependent function. Choose accordingly: use the null when the question is whether a ligand or analog acts through this receptor at all, and use db when comparability with the historical literature is the priority. Background dominates the phenotype, with frank beta-cell failure and diabetes on C57BLKS versus compensated hyperinsulinemic obesity on C57BL/6, so report the strain explicitly. Expect infertility, reduced linear growth and immune changes alongside obesity. Endpoints include weight trajectory, hyperphagia, fasting glucose and insulin, glucose tolerance, islet morphometry, and absence of arcuate phospho-STAT3 after leptin injection.',
  'Lepr:knockin':
    'Single-site substitution is what makes this receptor tractable, because the intracellular tyrosines route to separable effectors. Replacing the STAT3-docking tyrosine, reported as Y1138 in mouse Lepr, with serine or phenylalanine yields hyperphagic obesity while sparing the STAT5 and SHP2 arms, so growth, fertility and glucose handling separate from body weight in a way no null can show. Substituting the membrane-proximal tyrosine that recruits SHP2 and SOCS3 removes negative feedback instead and tests leptin resistance directly, and mutating the STAT5 site isolates reproductive and linear growth outputs. Box1 substitutions that block Jak2 docking give a signaling-dead receptor that still binds ligand. Cre and reporter knockins into this locus are also alleles, not neutral tools, so genotype for dosage and compare hemizygotes to wild type. Read phospho-STAT3 and phospho-STAT5 in arcuate nucleus, Pomc and Agrp transcripts, intake, and body composition.',
  'Lepr:humanized':
    'Humanize only for a biologics reason. Leptin itself is well conserved and recombinant human leptin activates the mouse receptor, so pharmacology of the natural ligand does not require a humanized allele. What does require it is antibody-based work: agonist, antagonist and bispecific antibodies recognize conformational epitopes in the human extracellular cytokine receptor homology and immunoglobulin-like modules, so replace the ectodomain-encoding exons and leave the transmembrane and intracellular sequence murine, which preserves normal Jak2 and STAT coupling and keeps the phenotype interpretable. If ligand affinity is part of the question, humanize Lep in the same animal, since a mismatched pair yields misleading potency. For monogenic human LEPR variants, a point knockin in the mouse locus is usually the cleaner and cheaper choice unless the residue lies in a diverged region. Validate by surface expression, ligand binding affinity, phospho-STAT3 dose response, and normal body weight at baseline.',
  'Pparg:conditional-knockout':
    'Germline deletion is off the table because of placental failure, so every question about this receptor in adults runs through a floxed allele. Flank the exons encoding the tandem zinc fingers so recombination removes DNA binding rather than only the ligand pocket, which prevents a receptor that still occupies PPRE sites without ligand response. Match the driver to the compartment: Adipoq-Cre for mature adipocytes, Pdgfra-CreERT2 for preadipocyte recruitment, Ucp1-CreERT2 for brown and beige fat, LysM-Cre or Itgax-Cre for macrophage polarization, Cd4-Cre for visceral regulatory T cells, and Villin-Cre for intestinal epithelium. Avoid Fabp4-Cre, which recombines embryonically and in macrophages and has generated conflicting adipose literature. Deleting in mature adipocytes triggers cell death and progressive lipodystrophy, so separate acute signaling loss from tissue loss by timed tamoxifen. Read fat pad mass, adipocyte diameter, serum adiponectin, ectopic lipid, glucose tolerance, and loss of thiazolidinedione response.',
  'Pparg:knockout':
    'A constitutive null cannot be maintained as homozygous because embryos are lost around midgestation from trophoblast and placental vascular failure, which is a placental requirement rather than an embryonic one. Two designs get around that. Epiblast-restricted deletion with Sox2-Cre or Meox2-Cre spares trophoblast and produces a functionally whole-body null that develops further, exposing the fetal requirement for lipid handling and cardiac function. Alternatively delete only the isoform-specific first exon that generates PPARG2, which is viable and adipose-restricted, and asks whether the extra amino-terminal segment contributes beyond total receptor dosage. Heterozygotes are worth keeping on the shelf, since reduced dosage is associated with protection from diet-induced insulin resistance, an outcome that argues against a simple more-is-better model. Endpoints are placental vascular architecture and lethality timing for the full null, and adipose mass, adipocyte size, insulin tolerance and hepatic triglyceride for the survivors.',
  'Pparg:knockin':
    'This locus rewards point mutation more than deletion because the receptor has separable functions. The dominant-negative substitution corresponding to human P467L sits in helix 12 of the ligand-binding domain and is numbered P465L in the mouse frame, a distinction worth getting right on the design document; heterozygotes reproduce partial lipodystrophy with insulin resistance and hypertension without loss of DNA binding, so the mutant still occupies PPRE sites and recruits corepressor. A serine to alanine change at the CDK5 and ERK target site in the hinge, numbered 273 in the PPARG2 frame, is the allele that separates insulin sensitization from classical agonism and predicts whether a non-agonist ligand should work. AF-2 substitutions that block coactivator docking give a third, ligand-blind receptor. Read adipose mass and distribution, adiponectin and Cd36 transcript sets, serum triglycerides, insulin tolerance, and blood pressure where the dominant negative is used.',
  'Pparg:humanized':
    'Humanization is usually the wrong spend here. The ligand-binding domain and DNA-binding domain are nearly identical between mouse and human, thiazolidinediones and endogenous fatty acid ligands act on the mouse receptor with comparable potency, and most clinical variants can be installed as point changes in the mouse locus. The defensible exception is the amino-terminal segment unique to PPARG2, where the human Pro12Ala polymorphism sits in sequence that does not align cleanly, so testing that variant means replacing the isoform-specific first exon and its upstream promoter with human sequence rather than substituting a residue. The same logic applies to human promoter and enhancer variants that alter isoform ratio. If humanization is undertaken, keep it minimal and confirm that PPARG1 and PPARG2 transcript ratio, receptor protein level, and agonist dose response match wild type before phenotyping adipose mass, insulin sensitivity, and target gene induction.',
  'Insr:conditional-knockout':
    'Beyond the standard metabolic drivers, this allele becomes interesting in tissues where insulin is not classically thought to act: Nes-Cre or Camk2a-CreERT2 for central control of feeding and hepatic glucose output, Cdh5-CreERT2 for endothelial transcytosis of insulin, Pdgfrb-CreERT2 for pericytes, Myh6-Cre for cardiac substrate use, and Ksp-Cre for tubular sodium handling. Flank the exon encoding part of the L1 ligand-binding module so recombination terminates translation upstream of the transmembrane segment and no membrane-anchored kinase-dead stub remains. Two confounds recur. Deleting in one insulin-responsive tissue raises circulating insulin, which then overstimulates the others, so always report fasting insulin alongside the phenotype. Residual signaling proceeds through Igf1r homodimers once hybrid receptor formation is lost, so consider compound deletion when the readout is Akt output rather than ligand specificity. Use hyperinsulinemic euglycemic clamps with tracer measurement of tissue glucose uptake plus phospho-Akt and Foxo1 target transcripts.',
  'Insr:knockout':
    'Homozygous nulls survive birth and then die within days from unrestrained lipolysis, hyperglycemia and ketoacidosis, so the allele supports only a narrow neonatal window. That window is still useful. Birth weight is reduced by roughly ten percent, which quantifies the contribution of Igf2 signaling through the A isoform to fetal growth, and postnatal day one to three tissue is enough for hepatic glycogen, lipolysis markers and receptor-proximal signaling. The more productive use is dosage genetics: heterozygotes are only mildly insulin resistant alone but become overtly diabetic when combined with Irs1 heterozygosity, which makes this allele a defined sensitizer for modifier screens. A hypomorphic design that lowers expression rather than eliminating it is the alternative when adult survival is required. Track survival curves, glucose and ketones from the first hours, birth weight, hepatic glycogen depletion, and insulin-stimulated phospho-Akt in explanted tissue.',
  'Insr:knockin':
    'The most distinctive alleles here are splice-directed rather than substitutions. Forcing constitutive inclusion or constitutive skipping of exon 11 locks the animal into IR-B or IR-A only, which tests isoform-specific affinity for insulin versus Igf2 and the tissue distribution that no conditional deletion can address. On the substitution side, mutating the juxtamembrane NPXY tyrosine abolishes Irs1 and Irs2 docking while leaving catalysis intact, the carboxy-terminal tyrosines separate Shc and Erk output, and replacing the activation loop tyrosines gives a kinase-dead receptor that still traffics and dimerizes, which distinguishes signaling from scaffolding and from receptor-mediated insulin clearance. Mouse residue numbering runs a few positions off the human sequence, so define positions against the mouse reference rather than copying clinical numbers. Read insulin-stimulated receptor autophosphorylation, Irs tyrosine phosphorylation, Akt and Erk branches separately, insulin clearance rate, glucose tolerance, and growth curves.',
  'Insr:humanized':
    'Restrict the swap to the ectodomain-encoding exons covering L1, the cysteine-rich region, L2 and the fibronectin modules, since that is where analogs and antibodies bind, and keep the transmembrane and kinase-encoding sequence murine so downstream coupling and mouse Irs interaction stay native. Two design consequences follow. Allosteric agonist antibodies engage a site in the first fibronectin module, so partial humanization must include it or the animal will look refractory. Hybrid receptor assembly with mouse Igf1r may be altered by a chimeric alpha subunit, so measure baseline growth and Igf1 responsiveness before interpreting any metabolic difference. If mitogenicity of an analog is the endpoint, humanizing Igf1r in the same line is necessary, because analog selectivity between the two receptors is species dependent. Confirm insulin binding affinity on primary adipocytes, receptor processing into alpha and beta chains, phospho-Akt dose response, glucose tolerance, and unchanged body weight.',
  'Foxo1:conditional-knockout':
    'Because germline nulls die near midgestation from failed vascular remodeling, tissue-restricted deletion is the only route to adult biology at this locus. Flank the exons encoding the forkhead DNA-binding domain rather than the transactivation tail, so any residual product cannot occupy DAF-16 family elements and cannot act as a dominant negative on Foxo3. Match driver to compartment: Alb-Cre or Alb-CreERT2 for hepatic gluconeogenesis, Ins1-Cre rather than older RIP-Cre lines that carry human growth hormone sequence and distort islet mass, Cdh5-CreERT2 for endothelial questions that recapitulate the lethality in adults, Vav-Cre or Mx1-Cre for hematopoietic stem cells. Expect partial phenotypes wherever Foxo3 and Foxo4 are coexpressed, so plan compound floxed alleles from the start. Read pyruvate tolerance, hepatic G6pc and Pck1 transcripts, fasting insulin, and stem cell quiescence by label retention.',
  'Foxo1:knockout':
    'A straight null is not a viable adult model, and the honest use of the allele is embryonic and cell-based. Homozygotes arrest with disorganized branchial arch and yolk sac vasculature, so the phenotype reports endothelial dosage rather than metabolism, and any metabolic question needs the floxed allele instead. The allele still earns its place. Heterozygotes are viable, and haploinsufficiency improves insulin sensitivity and attenuates diabetes in Irs2 deficient crosses, which makes the single-copy state a genetic modifier tool rather than a control. Null blastocysts and embryonic fibroblasts give clean systems for autophagy flux, Cdkn1b induction, and oxidative stress resistance without Cre variability. Delete across the forkhead exons and confirm loss by immunoblot rather than transcript, since truncated species accumulate. Score lethality timing, vessel morphology, and compensatory Foxo3 and Foxo4 expression.',
  'Foxo1:knockin':
    'This is where the locus is most informative, because activity is set by post-translational marks rather than abundance. A triple alanine substitution at the three AKT sites, introduced at the endogenous locus rather than as a CAG transgene, yields a protein that stays nuclear under insulin and reports what constitutive activity does to gluconeogenesis and beta cell dedifferentiation at physiological dosage. Complementary designs include arginine substitution at the SIRT1 regulated acetylation lysines to fix the deacetylated state, and a DNA-binding-deficient helix mutant that isolates cofactor scaffolding from transcription. For alveolar rhabdomyosarcoma, a Cre-dependent Pax3-Foxo1 fusion knockin placed under endogenous Pax3 control models the translocation more faithfully than overexpression. Read subcellular fractionation, chromatin immunoprecipitation at G6pc and Pck1, 14-3-3 coimmunoprecipitation, and insulin suppression of hepatic glucose output.',
  'Foxo1:humanized':
    'Be skeptical about coding humanization here. The forkhead domain and the sequence context around the kinase sites are nearly identical between mouse and human, so a human cDNA swap will not change signaling behavior and does not create a better target for available transcriptional inhibitors, which do not discriminate species. The defensible reason to humanize is nucleotide sequence rather than protein. Antisense oligonucleotides and small interfering RNAs are selected against human transcript, so a knockin carrying human coding exons plus the human three prime untranslated region gives an animal in which candidate oligos engage their real target and in which untranslated region variants and microRNA sites become testable. If the question is antibody or protein-protein pharmacology, humanize the upstream receptor instead. Confirm human transcript by allele-specific PCR, verify unchanged basal expression, and read knockdown alongside gluconeogenic output.',
  'Fgf21:conditional-knockout':
    'Since nulls survive, the conditional allele exists to answer a source question, not a viability question. Flanking the exons that encode the mature secreted peptide, including the carboxy-terminal segment that docks beta-Klotho, removes bioactivity without leaving a signal peptide fragment that could still be secreted. Alb-Cre removes the hepatocyte pool that dominates fasting and ketogenic plasma levels, but recombination completes only after birth, so early developmental contributions escape. Adipoq-Cre addresses the autocrine adipose pool, Ckmm-Cre the exercise and mitochondrial stress pool, and Ptf1a-Cre the acinar pool that confuses whole-body interpretation. Pair each with a Klb conditional on the receiving side, because deleting the ligand cannot distinguish adipose from hindbrain responsiveness. Measure plasma protein to confirm compartment loss, then read fasting ketogenesis, adiponectin, energy expenditure, and sucrose preference.',
  'Fgf21:knockout':
    'Constitutive deletion suits this gene because homozygotes are viable, fertile, and near normal on chow, which makes the allele a challenge-dependent reporter rather than a spontaneous disease model. Remove the whole coding region including the exon encoding the beta-Klotho contact surface, since partial truncations can retain FGFR1c affinity and produce ambiguous partial agonism. The phenotype appears only under stress, so build the protocol before the mouse: ketogenic and low protein diets to test the PPARalpha and ATF4 driven arms, thermoneutral housing to unmask thermogenic contributions, and two-bottle sweet and ethanol tests for the central preference axis. Two caveats matter. Strain background shifts diet responses, so littermate controls on one background are non-negotiable, and a null cannot show whether analogs act through the endogenous axis, which requires Klb deletion. Read ketone bodies, growth under protein restriction, adiponectin, and preference ratios.',
  'Fgf21:knockin':
    'Two knockin classes earn their keep here. The first is a protease-resistant allele. Substituting residues at the fibroblast activation protein cleavage site in the carboxy-terminal region prevents inactivating cleavage while leaving the beta-Klotho docking sequence intact, so half-life rises without changing receptor selectivity, and the mouse becomes a genetic control for engineered analogs. The second is a reporter or driver allele. A bicistronic luciferase or fluorophore inserted before the stop codon lets you image PPARalpha and ATF4 driven induction in living animals during fasting or amino acid restriction, and an inducible Cre in the same configuration marks cells that have transcribed the gene. Keep insertions out of the promoter and preserve the untranslated regions, since transcript stability is part of the regulation. Read plasma clearance kinetics, cleaved versus intact protein, and induction amplitude against dietary challenge.',
  'Fgf21:humanized':
    'Here the case for humanization needs care. Human and mouse proteins are roughly four fifths identical and the human protein activates mouse beta-Klotho with FGFR1c, so analog efficacy studies do not strictly require a humanized ligand. What a humanized knockin does deliver is a clean matrix for human-specific immunoassays, so endogenous and dosed protein can be distinguished, plus a substrate carrying the authentic human cleavage sequence for measuring proteolytic inactivation and half-life. It also permits testing human coding variants at the endogenous locus. If the goal is potency or receptor selectivity of an engineered agonist, humanize Klb or the FGFR1c ligand-binding region instead, since coreceptor contacts set most of the species gap. Verify wild type expression under fasting induction, then read intact versus cleaved species, clearance, adipose glucose uptake, and energy expenditure.',
  'Adipoq:conditional-knockout':
    'The honest first observation is that expression is already nearly adipocyte-restricted, so a global null is close to a tissue-specific null, and the conditional allele buys timing and depot resolution rather than specificity. Use it when you need adult-onset deletion after adipose tissue has formed, which separates developmental effects on depot expansion from acute insulin sensitization. Depot questions are better served by Ucp1-CreERT2 for brown and beige adipocytes and Pdgfrb-CreERT2 for progenitor-derived cells. Avoid drivers built on adiponectin regulatory sequence, which are circular against this floxed target and may themselves shift dosage, and treat Fabp4-Cre with suspicion because it also recombines in macrophages and endothelium. Flank the exons encoding the globular C1q-like head so no assembly-competent fragment survives. Confirm loss by high molecular weight immunoassay, then clamp for insulin sensitivity and quantify hepatic triglyceride and ceramide species.',
  'Adipoq:knockout':
    'Constitutive deletion is a defensible primary allele, since homozygotes are viable and fertile with only mild chow phenotypes and the biology becomes visible under lipid load. Delete the entire coding region, both the collagen-like stalk exons and the globular head exons, because removing one domain can leave a secreted fragment that occupies receptors or distorts assembly of the remaining product. Interpret the allele against published discordance. Independently constructed nulls differ in the severity of diet-induced insulin resistance, and background plus deletion boundaries explain much of that, so state your strategy and use littermate controls on a fixed background. High fat feeding, lipid infusion, thiazolidinedione response, and crosses onto Apoe or Ldlr nulls for vascular endpoints are where the phenotype lives. Read glucose and insulin tolerance, free fatty acid clearance, tissue ceramide, and adipose macrophage infiltration rather than plasma protein alone.',
  'Adipoq:knockin':
    'This locus rewards structure-function knockins more than deletion. Substituting the conserved cysteine in the collagen-like stalk blocks disulfide-dependent formation of hexamers and high molecular weight oligomers while leaving trimer secretion intact, which separates assembly from production and tests directly whether the high molecular weight species carries insulin sensitization. Mutating the conserved stalk lysines that undergo hydroxylation and glycosylation is the complementary experiment, since those modifications are required for higher order assembly. A globular-head-only allele isolates the fragment reported to act through AMPK, and knockins of human missense variants associated with hypoadiponectinemia give an allelic series rather than an on or off comparison. Add an epitope tag only at a terminus validated not to disturb oligomers. Resolve species by velocity gradient or native gel plus high molecular weight immunoassay, then clamp and measure hepatic ceramide.',
  'Adipoq:humanized':
    'Humanize this locus when the reagent, not the pathway, is species-restricted. Antibodies and immunoassays raised against human adiponectin often read the mouse protein poorly, and any biologic that targets the ligand or its assembly needs human sequence to bind. A knockin carrying human coding exons also lets you test regulatory variation, since the human promoter and untranslated regions contain polymorphisms linked to circulating levels that cannot be modeled with mouse sequence. Include the human collagen-like stalk, not only the globular head, because oligomer distribution is the phenotype and stalk residues determine it. Do not humanize here if the compound is a receptor agonist acting on Adipor1, Adipor2, or T-cadherin; humanize the receptor instead. Validate that human high molecular weight fractions form at physiological ratios, confirm normal plasma concentration, then read clamp-based insulin sensitivity and target engagement.',
  'Glp1r:conditional-knockout':
    'Because whole-body deletion cannot separate insulin secretion from appetite, this is the allele that matters for mechanism. Flank the exons encoding the extracellular domain that captures the peptide carboxy terminus, so no truncated receptor remains that might still couple weakly. Assign compartments deliberately: Ins1-Cre for beta cells, Phox2b-Cre or Slc17a6-CreERT2 for hindbrain and nodose populations, Calcr-Cre for area postrema neurons implicated in nausea and anorexia, Chat-Cre for cholinergic vagal efferents. Two practical problems recur. Transcript abundance is low, so verify recombination by in situ hybridization or single-cell sequencing rather than bulk PCR, and many available drivers are knockins at this locus that reduce receptor dosage on the driver allele, which biases dose-response work. Read glucose-stimulated insulin secretion in vivo and from isolated islets, gastric emptying, cumulative food intake, body weight, and agonist-induced taste avoidance.',
  'Glp1r:knockout':
    'The strongest use of a straight null is as a specificity control. Homozygotes are viable with mild fasting hyperglycemia and blunted glucose-stimulated insulin secretion, and their complete failure to respond to exenatide, liraglutide, or semaglutide is what proves an in vivo effect is receptor mediated rather than off target, including the weight loss and gastric emptying components. Delete across the coding exons rather than the promoter, and confirm absence of protein by radioligand binding or a validated antibody, since transcript-based checks are unreliable at low abundance. Interpretation requires two cautions. Lifelong absence permits compensation, notably increased reliance on Gipr, so pair with Gipr nulls or double receptor mutants when the incretin axis is the subject, and developmental effects on islet architecture and ventricular wall thickness confound adult readouts. Score oral and intraperitoneal glucose tolerance, insulin secretion, gastric emptying, and agonist nonresponsiveness.',
  'Glp1r:knockin':
    'Point-mutant and tagged knockins address questions deletion cannot. Substitutions in the transmembrane bundle that shift coupling toward Gs and away from beta-arrestin recruitment let you test in vivo whether biased agonism explains why some analogs produce less nausea, and mutations in the extracellular peptide-capture surface separate affinity from efficacy. A signaling-dead but binding-competent receptor is a useful sink allele for asking whether ligand sequestration alone changes exposure. Because good antibodies are scarce, insert a small extracellular tag such as SNAP or a validated epitope into a loop that does not disturb the two-domain binding mechanism, which finally makes surface trafficking and internalization measurable in tissue. Keep reporter cassettes bicistronic and confirm dosage is unchanged. Read cyclic AMP and insulin secretion from isolated islets, receptor internalization, gastric emptying, and food intake across full dose-response curves.',
  'Glp1r:humanized':
    'This is the clearest humanization case in the set. Peptide potency differs between species at the extracellular domain, and the oral small molecule agonists now in development bind a pocket formed largely by the transmembrane region and the first extracellular loop, where residue differences leave the mouse receptor essentially unresponsive, so an animal carrying human coding sequence at the endogenous locus is the only setting in which those compounds can be dosed meaningfully. Replace the full coding region rather than a single domain, since both the peptide-capture surface and the small molecule pocket matter, and keep mouse regulatory sequence so expression and dosage in islets, hindbrain, and vagal afferents remain native. Confirm equivalent transcript abundance and normal baseline glucose handling before pharmacology, then read islet cyclic AMP, glucose tolerance, food intake, body weight, and gastric emptying against a validated peptide comparator.',
  'Tnf:conditional-knockout':
    'Cell-source attribution is the point, and it is harder than usual because this cytokine acts at picomolar concentration, so deletion escapees can carry the phenotype. Design floxed sites entirely within the locus, keeping the neighboring lymphotoxin genes and the shared regulatory interval intact, and verify by sequencing that no enhancer used by Lta is removed. Pair drivers to the model: LysM-Cre for macrophage and neutrophil sources in endotoxemia, Cd4-Cre and Cd19-Cre for lymphocyte-derived cytokine in colitis and arthritis, Villin-Cre for intestinal epithelium, Cx3cr1-CreERT2 for microglia with tamoxifen timed to allow monocyte turnover. LysM-Cre deletes unevenly between neutrophils and tissue macrophages, so quantify recombination in sorted populations and measure cell-specific secretion ex vivo rather than serum alone. Endpoints include serum concentration after lipopolysaccharide, survival, joint histology with clinical scoring, and intestinal permeability.',
  'Tnf:knockout':
    'A complete null is right when the question is whether the cytokine is required at all, and wrong when the question is which form or which source matters, because it removes membrane and soluble activity together. Homozygotes are viable but show impaired containment of Listeria and mycobacteria with disorganized granulomas, blunted follicular dendritic cell networks, and resistance to lipopolysaccharide-induced shock and to collagen-induced arthritis, which makes the allele both an infection risk model and a negative control for anti-cytokine efficacy. Two design cautions apply. Because the locus sits beside Lta and Ltb, retained selection cassettes and large deletions in older lines can perturb lymphotoxin function and mimic the same lymphoid architecture defects, so use a cassette-free allele and genotype the neighbors. Backcross fully, since background dominates infection outcomes. Read bacterial burden, granuloma histology, splenic and Peyer patch organization, and survival after endotoxin.',
  'Tnf:knockin':
    'Knockins are the most informative alleles here because they change form and stability rather than presence. Deleting the AU-rich element in the three prime untranslated region removes tristetraprolin-dependent decay, raises steady-state transcript cell-autonomously, and produces ileitis with erosive peripheral arthritis, giving a spontaneous chronic model rather than an induced one; keep the deletion minimal so neighboring stability elements survive. An uncleavable allele, made by altering the ADAM17 cleavage region so the trimer stays membrane anchored, isolates juxtacrine signaling and shows which functions require systemic exposure. The reciprocal soluble-only design is harder to interpret, since tethering also concentrates receptor engagement. Reporter knockins placing a fluorophore behind the coding sequence identify producing cells in situ. Score transcript half-life, shed versus surface protein by flow cytometry and immunoassay, ileal histology, arthritis incidence, and receptor-selective NF-kB activation.',
  'Tnf:humanized':
    'Full humanization is not optional for antibody work, since infliximab and adalimumab do not bind the mouse cytokine, and certolizumab and etanercept behave the same way. Replace the coding exons with human sequence at the endogenous locus so transcriptional control, including the AU-rich element and enhancers shared with the lymphotoxin interval, stays mouse and expression timing remains physiological. One asymmetry must be planned for. Human protein engages mouse TNFRSF1A but signals poorly through mouse TNFRSF1B, so a ligand-only humanized mouse reports receptor one biology and underestimates receptor two contributions, including regulatory T cell effects. If receptor two matters, humanize TNFRSF1B as well or use a double humanized line. Validate with a human-specific immunoassay, confirm ADAM17 shedding of the human sequence, then read target engagement, neutralization in endotoxemia or arthritis, immunogenicity, and dose-dependent NF-kB suppression.',
  'Il6:conditional-knockout':
    'Conditional deletion answers which cell makes the cytokine, a question a null cannot touch, and here the candidate sources are unusually diverse. Flank the coding exons for the four-helix bundle, including the surface that contacts the alpha chain, and keep untranslated regulatory elements in the floxed footprint unchanged so transcript stability is not altered on the unrecombined allele. Choose drivers by model: LysM-Cre for myeloid production in endotoxemia, Col1a2-CreERT2 or Pdgfrb-CreERT2 for stromal fibroblast production in arthritis and tumor stroma, Cdh5-CreERT2 for endothelium, Ckmm-Cre for the exercise-induced muscle pool, Gfap-CreERT2 for astrocytes in neuroinflammation. Because plasma concentration is dominated by whichever compartment is activated, quantify recombination in sorted cells and measure secretion ex vivo. Read serum amyloid A, hepatic Stat3 phosphorylation, Socs3 induction, splenic Th17 frequency, and plasma cytokine.',
  'Il6:knockout':
    'A straight null is the right first pass for necessity questions and the wrong tool for mechanism, since it removes classic and trans-signaling at once. Homozygotes are viable and fertile with a markedly blunted acute phase response, impaired control of Listeria and other pathogens, near resistance to collagen-induced arthritis and to experimental autoimmune encephalomyelitis, and delayed liver and skeletal muscle regeneration after injury. Two interpretive traps recur. Modest phenotypes often reflect Il11, Lif, and Osm converging on the same gp130 receptor, so compensation should be measured rather than assumed, and protection in metabolic models has been inconsistent across colonies, pointing to microbiome and background effects that require cohousing and littermate controls. Delete the full coding region and confirm absence of protein by bioassay as well as immunoassay. Read serum amyloid A, haptoglobin, Stat3 phosphorylation, Th17 frequency, and regeneration endpoints.',
  'Il6:knockin':
    'Two designs stand out. First, a stability knockin: mutating the Regnase-1 and Arid5a responsive elements in the three prime untranslated region raises steady-state transcript without changing which cells transcribe the gene, producing chronic low-grade signaling that models inflammatory anemia, thrombocytosis, and cachexia more faithfully than repeated injection. Second, a conditional gain-of-function allele in which a lox-stop-lox cassette precedes a fusion of the cytokine to the soluble alpha chain, which forces trans-signaling onto gp130-positive cells in the lineage of your choice and isolates that arm cleanly. Reporter knockins with a fluorophore or luciferase behind the coding sequence identify producing cells in vivo, where antibody staining is unreliable. Avoid amino-terminal tags, which sit near the alpha chain interface. Read plasma cytokine and soluble receptor, hepatic Socs3 and acute phase transcripts, Stat3 phosphorylation, hematocrit, platelet counts, and body composition.',
  'Il6:humanized':
    'Match the humanized gene to the drug. Siltuximab binds the cytokine, so a humanized ligand knockin is required, while tocilizumab and sarilumab bind the alpha chain, so humanizing Il6ra is the correct target and a humanized ligand alone will not report their pharmacology. Species behavior is asymmetric and worth planning around: human cytokine can act on mouse receptor complexes, whereas mouse cytokine does not activate the human receptor, which means a humanized ligand line stays signaling competent but a humanized receptor line needs human ligand to be fully informative, arguing for a double humanized cross when both arms are in play. Replace coding exons only and keep mouse promoter and untranslated regulation so induction kinetics stay native. Validate with a human-specific immunoassay and a human cell bioassay, then read target engagement, acute phase suppression, Stat3 phosphorylation, and arthritis scores.',
  'Il10:conditional-knockout':
    'Interleukin 10 is secreted and freely diffusible, so a conditional null only informs when the deleted compartment is a dominant source rather than a bystander consumer; pair every driver with a reporter allele confirming the cell actually transcribes it. Flanking exon 1, which carries the signal peptide and the first helix, eliminates secretion competence without leaving a truncated helical fragment able to occupy IL10RA. Cd4-Cre and Itgax-Cre interrogate T cell and dendritic sources, Cx3cr1-CreERT2 reaches intestinal macrophages but requires tamoxifen timing that accounts for monocyte replacement of the labeled pool, and Lyz2-Cre deletes incompletely in lamina propria macrophages, so quantify recombination on sorted cells. Interpretable endpoints are blinded histologic colitis scoring, colon length, lipopolysaccharide induced serum TNF and interleukin 12p40, and ex vivo restimulation supernatants, all read in cohoused littermates under defined Helicobacter status.',
  'Il10:knockout':
    'Germline deletion is well tolerated at birth and remains the standard sensitized chassis for microbiota and therapeutic work, which is its real value: the null is a background, not an explanation. Remove the coding exons entirely rather than a single exon, since partial deletions can leave transcripts encoding fragments that are detectable by antibody but inactive, complicating protein level validation. Background then dominates phenotype. On 129 and BALB/c backgrounds colitis is early and penetrant; on C57BL/6 it is late and mild, and most laboratories accelerate it with piroxicam or with defined Helicobacter hepaticus colonization, both of which must be reported as part of the genotype. Because loss is constitutive, developmental compensation through TGF beta and interleukin 27 driven regulatory circuits cannot be excluded. Score weight loss, colon length, blinded histology, fecal lipocalin 2, and serum interleukin 12p40 against cohoused wild type littermates.',
  'Il10:knockin':
    'Most useful Il10 knockins are reporters and fate mappers, and their design turns on the 3 prime untranslated region, which carries AU rich elements setting transcript half life; inserting a cassette there destroys post-transcriptional control and inflates apparent expression. Place a T2A linked fluorophore or recombinase immediately before the stop codon instead, preserving that region and giving stoichiometric readout, since IRES configurations underreport low expressing cells such as Tr1 populations. A Cre knockin permits permanent labeling of cells that have ever transcribed Il10, which matters because expression is transient and stimulus dependent. Point knockins at the dimer interface test whether monomeric variants retain receptor engagement. Validate any reporter against intracellular cytokine staining and ELISA on sorted populations, and confirm the allele has not reduced secreted protein by comparing homozygous reporter animals with wild type after lipopolysaccharide challenge.',
  'Il10:humanized':
    'Species cross reactivity is asymmetric here: human interleukin 10 signals on mouse cells, whereas mouse interleukin 10 does not act on human cells. That asymmetry means humanizing the ligand alone rarely answers the question, because the therapeutics in this space are antibodies and engineered agonists whose selectivity is set by the receptor epitope. Humanize Il10ra, or both Il10 and Il10ra, if the goal is target engagement by a receptor directed reagent. Build by replacing coding exons with the human orthologous sequence while retaining mouse promoter, introns, and untranslated regions so expression stays restricted to the physiologic sources. Confirm the humanized chain still pairs with mouse IL10RB before trusting any phenotype, since the shared chain is not replaced. Read out phosphorylated STAT3 in myeloid cells, Socs3 induction, drug pharmacokinetics, and rescue of colitis on an Il10 null background.',
  'Il17a:conditional-knockout':
    'Locus architecture constrains this design. Il17a sits immediately upstream of Il17f and the two share intergenic conserved noncoding enhancers, so loxP sites must fall within Il17a introns and the deleted segment must stop short of those elements; a careless floxed allele silences Il17f in cis and produces a covert double mutant. Target the exons encoding the cystine knot rather than the signal peptide, since knot disruption abolishes both homodimer and heterodimer assembly. Rorc-Cre also recombines in double positive thymocytes and ILC3s, broadening loss beyond the intended compartment, while Tcrd-CreERT2 restricts to gamma delta cells but recombines inefficiently in tissue resident subsets. Verify deletion by intracellular cytokine staining after PMA and ionomycin, not by genomic PCR. Score imiquimod ear thickening, oral Candida albicans burden, EAE course, and tissue Cxcl1 and Lcn2 transcripts.',
  'Il17a:knockout':
    'A germline null is viable and fertile, and its interpretive ceiling is set by interleukin 17F, which keeps signaling through the same receptor complex; expect partial phenotypes and plan a graded series in which Il17a single, Il17a with Il17f, and Il17ra alleles give progressively stronger defects. Delete the full coding region so no cystine knot fragment survives to enter heterodimers. Because targeting used 129 derived cells and the locus lies on chromosome 1, a linked 129 interval travels with the mutation through backcrossing, so compare against littermates carrying that same flanking region rather than against colony wild types. Susceptibility to oropharyngeal Candida albicans and to cutaneous Staphylococcus aureus is the most reliable positive control that the allele works. Add EAE scoring, imiquimod psoriasiform inflammation, and neutrophil recruitment quantified with Cxcl1 and Csf3 measurement.',
  'Il17a:knockin':
    'Because interleukin 17A expression is transient and heavily regulated after transcription, cassette placement decides whether a knockin reports biology or artifact. Insert a T2A linked fluorophore or recombinase immediately upstream of the stop codon so the secreted cytokine keeps its native carboxy terminus, and leave the 3 prime untranslated region intact, since Regnase 1 and Arid5a act there to set transcript stability. Dual reporter designs at Il17a and Il17f in the same animal resolve which producers make heterodimers, a distinction no single reporter can draw. Structure guided point knockins at the receptor binding surface can yield a mutant that dimerizes normally yet cannot engage IL-17RA, separating assembly from signaling. Validate by comparing reporter positive frequencies with intracellular staining, confirm secreted protein by ELISA, and check that homozygous knockin animals still clear Candida albicans normally.',
  'Il17a:humanized':
    'Human and mouse interleukin 17A diverge enough that the clinical antibodies do not bind the mouse protein, which is precisely what makes coding region humanization worthwhile here, unlike genes whose sequences are effectively identical. Replace the mouse coding exons with human orthologous exons while retaining the mouse promoter, introns, and the intergenic enhancers shared with Il17f, so expression stays confined to RORgt dependent producers. The design rests on an assumption, that human interleukin 17A still engages the mouse IL-17RA and IL-17RC complex; verify it directly by measuring CXCL1 induction in mouse embryonic fibroblasts before committing to in vivo work, because failure there silently converts the allele into a knockout. Humanize Il17f in parallel if heterodimer neutralization matters. Endpoints are imiquimod ear thickness with dose ranging, free versus total human cytokine, and target occupancy over time.',
  'Foxp3:conditional-knockout':
    'X linkage shapes everything. Hemizygous males carrying a floxed allele lose the gene completely once Cre acts, while heterozygous floxed females are mosaic through X inactivation and therefore supply an internal competition assay in which deleted and intact regulatory T cells coexist in one animal, a far more sensitive test of cell intrinsic requirement. Flank the exons encoding the forkhead domain so no DNA binding deficient protein persists to occupy partner complexes. Foxp3-CreERT2 gives timed, lineage restricted deletion, but the deleted cells survive as former regulatory effectors, so add a constitutive Rosa26 lineage tracer to separate loss of suppression from acquisition of pathogenic function. Cd4-Cre instead deletes before the lineage forms and models developmental failure. Endpoints are survival, dermatitis and blepharitis scoring, CD44 high CD62L low expansion, serum IgE, autoantibodies, and in vitro suppression assays.',
  'Foxp3:knockout':
    'A germline null is not a tool with a long working window; hemizygous males develop lymphoproliferative wasting, scaly ears and tails, and hepatosplenomegaly, and die within roughly the first month, so every experiment must fit inside that interval. Colony management follows. Maintain through heterozygous females, genotype sex and allele together, and expect heterozygous females to stay largely healthy because wild type regulatory T cells outcompete deleted ones. Delete the promoter with the first coding exon, or the entire coding region, rather than an internal exon that could yield an amino terminal repressor fragment. Use this allele for rescue studies, asking whether transfer of wild type or engineered regulatory cells prevents disease, and for bone marrow chimeras. Endpoints are survival curves, weight, infiltrates in skin, lung, liver and pancreas, activated T cell frequencies, and autoantibody titers.',
  'Foxp3:knockin':
    'Cassette placement is the main hazard, because the conserved noncoding sequence 2 enhancer and its demethylated regulatory region lie inside the locus and control heritable expression; a selection marker or reporter that perturbs them destabilizes the lineage and confounds everything downstream, so excise selection with Flp and sequence the region afterward. Amino terminal fluorescent fusions have been reported to alter protein function and regulatory T cell fitness, so prefer a bicistronic or T2A configuration and confirm protein per cell matches wild type. Structure guided substitutions in the leucine zipper block dimerization while sparing DNA binding, and changes in the amino terminal repressor module disrupt corepressor recruitment, giving separation of function alleles no null can provide. Read out suppression assays, methylation state of the regulatory region, target gene occupancy, and lineage stability under inflammatory challenge.',
  'Foxp3:humanized':
    'Coding humanization is usually the wrong instrument for this gene. FOXP3 is an intracellular transcription factor, so no antibody or biologic engages it, and the mouse and human proteins are close enough across the forkhead and leucine zipper regions that murine partners, Runx1 with CBF beta, NFAT, and the corepressor complexes, engage the human protein. For IPEX variant modeling, a single residue knockin at the mouse locus answers the same question with less risk of altered expression. Humanization earns its place when the reagent is sequence specific rather than protein specific: guide RNA directed editing, base editing correction, or oligonucleotide approaches designed against human sequence, and validation of human targeted gene therapy in an immunocompetent animal. Build it as a genomic coding replacement preserving mouse regulatory elements, then confirm suppressive function before layering a patient variant on top.',
  'Stat3:conditional-knockout':
    'Choose the floxed interval so no fragment survives that can still dimerize. Flanking the exons encoding the SH2 domain prevents recruitment to receptor phosphotyrosines and avoids a truncated product that retains DNA binding and acts dominantly. Driver choice carries specific baggage. Lyz2-Cre deletion produces spontaneous chronic enterocolitis because myeloid cells lose interleukin 10 responsiveness, effectively phenocopying interleukin 10 deficiency and contaminating any other readout in that animal. Vil1-Cre impairs mucosal wound repair and worsens dextran sulfate sodium injury, Alb-Cre abolishes the hepatic acute phase response, Krt14-Cre disturbs hair cycling, and Cd4-Cre blocks Th17 differentiation. Because the protein is abundant and stable, confirm loss by phospho-Tyr705 flow cytometry after interleukin 6 or interleukin 10 stimulation rather than by genomic PCR, and use Socs3 induction as the functional readout.',
  'Stat3:knockout':
    'Germline loss kills the embryo shortly after implantation, before gastrulation completes, so the null exists to serve other alleles rather than to be phenotyped. Three legitimate uses remain. First, embryonic stem cell work, where the requirement for LIF driven self renewal makes the null informative in culture. Second, tetraploid complementation and chimera analysis for early lineage questions. Third, and most practical, placing the null in trans to a conditional allele so a single recombination event yields complete loss, which rescues experiments where a weak or mosaic driver leaves too many intact alleles. Do not use heterozygotes to model hyper-IgE syndrome; patient alleles act dominant negatively rather than by haploinsufficiency, so a heterozygote carries half the normal protein and none of the interfering species. Score embryo staging, epiblast morphology, and colony formation under defined stem cell conditions.',
  'Stat3:knockin':
    'Single residue alleles need clean construction. Remove the selection cassette with Flp, because a retained marker in a Stat3 intron reduces transcript output and creates a hypomorph that will be misread as the point mutation acting. Include a silent restriction site or synonymous change to permit allele specific genotyping and confirm the edit survived subcloning. Gain of function alleles should be built as Cre inducible, using lox-stop-lox or inverted exon designs, since constitutive activation drives lymphoproliferation that compresses the experimental window; keeping the mutant silent until adulthood separates developmental from acquired effects. Avoid synthetic disulfide forced dimerizing constructs if patient biology is the goal, since they overshoot what any germline variant achieves. Read out baseline phospho-Tyr705, Socs3 and Bcl3 transcripts, large granular lymphocyte expansion, autoantibodies, and reversal with a JAK1 selective inhibitor.',
  'Stat3:humanized':
    'There is little pharmacological argument for humanizing this gene. STAT3 is cytosolic, no clinical antibody engages it, and JAK inhibitors act on upstream kinases that a Stat3 replacement does not alter. The mouse and human proteins are also nearly identical across the DNA binding, linker, and SH2 domains, so partner interactions are conserved and a patient variant knocked into the mouse locus behaves like the same variant in human sequence context at far lower cost. The defensible use case is at the nucleotide level: antisense oligonucleotides, small interfering RNA, decoy oligonucleotides, and targeted editing reagents are designed against human sequence and will not engage the mouse transcript. For that purpose replace the genomic coding region with its untranslated regions, keep mouse regulatory elements, and confirm normal expression before dosing. Read transcript and protein knockdown alongside Socs3 and acute phase responses.',
  'Stat6:conditional-knockout':
    'Design so the deleted allele cannot make an interfering product. Flanking the exons encoding the DNA binding domain removes target occupancy while leaving no species that still dimerizes through the SH2 domain and titrates partners. Useful drivers beyond the obvious lymphoid ones include Cd79a-Cre for early B cells, which deletes more completely than Cd19-Cre, Scgb1a1-CreERT2 for club cells and Foxj1-CreERT2 for ciliated cells when airway epithelial remodeling is the question, and Vil1-Cre for the intestinal tuft and goblet cell circuit driven by interleukin 25 and interleukin 13. The main pitfall is protein persistence, since STAT6 is long lived and recombination at the DNA level precedes functional loss by days. Confirm with phospho-STAT6 induction after interleukin 4 stimulation ex vivo. Endpoints are bronchoalveolar eosinophils, serum IgE, Retnla and Chil3 expression, and periodic acid Schiff staining.',
  'Stat6:knockout':
    'The germline null is healthy at baseline, breeds normally, and is the cleanest available switch for the entire type 2 axis, which is exactly why it works better as a comparator than as an explanatory allele. Its most productive applications are compartment splitting experiments: bone marrow chimeras separating hematopoietic from stromal requirement, and transfer of wild type or deficient T cells into null hosts to ask whether STAT6 is needed in the responder or in the tissue. Background matters more than usual, since BALB/c animals carry a stronger baseline type 2 bias and give larger effect sizes in allergen models than C57BL/6. Delete the coding exons completely rather than an internal segment. Score Nippostrongylus brasiliensis expulsion kinetics and worm burden, airway hyperresponsiveness by forced oscillometry, serum IgE, Gata3 expression, and intestinal tuft cell frequency.',
  'Stat6:knockin':
    'The most informative knockins here are patient derived gain of function substitutions in the DNA binding domain, described in children with early onset atopy, severe eczema, food allergy, and very high IgE. Introduce the substitution at the endogenous locus rather than expressing it from a transgene, since dosage decides whether the phenotype resembles the human disease or an artifact of overexpression, and consider a Cre inducible configuration if the constitutive allele proves too severe to breed. A phosphorylation dead substitution at the activating carboxy terminal tyrosine gives the opposite pole and behaves like a null with protein still present, which is useful for chromatin occupancy comparisons. Reporter knockins add little because expression is ubiquitous. Score spontaneous dermatitis, serum IgE, blood and tissue eosinophils, Th2 skewing in vitro, and reversal by upstream receptor blockade or JAK inhibition.',
  'Stat6:humanized':
    'Be clear about what humanization at this locus can and cannot support. STAT6 sits inside the cell, so it is not the target of the type 2 biologics; dupilumab binds IL-4R alpha, and a humanized Stat6 allele contributes nothing to that pharmacology. If antibody testing is the goal, humanize Il4ra, and Il13ra1 where the type II receptor matters. Humanized Stat6 is justified for two purposes: placing human coding variants in native sequence context when the divergent linker and transactivation regions are implicated, and enabling sequence specific reagents such as antisense oligonucleotides or targeted editing designed against the human transcript. Build it as a genomic coding replacement with mouse regulatory elements retained so expression follows normal kinetics, then verify the human protein is recruited efficiently by the mouse IL-4R alpha chain before reading any blunted phenotype as drug effect.',
  'Nfkb1:conditional-knockout':
    'A conditional allele here cannot separate p105 from p50, since floxing the exons encoding the Rel homology domain removes both at once; if precursor function is the question, use a processing mutant instead. What conditional deletion does deliver is compartment assignment, and the expected direction of effect is not always downward. Because p50 homodimers occupy kappaB sites without a transactivation domain and act as repressors, deletion in myeloid cells with Lyz2-Cre often raises rather than lowers inflammatory transcription. Cd79a-Cre or Cd19-Cre addresses the intrinsic B cell defect in class switching, and Vil1-Cre tests epithelial restraint of colitis. Expect loss of the p105 scaffold to destabilize MAP3K8 protein and reduce ERK output, an off axis consequence to be measured rather than assumed absent. Read kappaB occupancy by supershift or ChIP, and cytokine output after lipopolysaccharide.',
  'Nfkb1:knockout':
    'Choose the genotype to match the human disease. NFKB1 haploinsufficiency is the most frequently identified monogenic cause of common variable immunodeficiency, so heterozygous animals, not homozygous nulls, are the allelic match, and their phenotype is mild enough that aging cohorts and deliberate immunization are needed to reveal it. Homozygous nulls remain viable and answer a different question about total pathway architecture. Delete the exons encoding the Rel homology domain and confirm no ankyrin repeat only product remains, since a free carboxy terminal fragment would keep sequestering RelA and c-Rel and would confuse loss of function with gain of inhibition. Immunize with a hapten carrier conjugate and measure class switched and affinity matured titers, enumerate marginal zone and B1 compartments, challenge with Streptococcus pneumoniae or Listeria monocytogenes, and follow aged cohorts for spontaneous inflammation and autoantibodies.',
  'Nfkb1:knockin':
    'Knockins are the only way to dissect a gene encoding two functionally opposed products from one transcript. Mutating the glycine rich region that directs cotranslational processing yields precursor only animals, while a stop introduced after the Rel homology domain yields p50 only and simultaneously eliminates the inhibitory ankyrin segment and the scaffold that stabilizes MAP3K8, so those mice lose TPL2 protein and ERK responsiveness to lipopolysaccharide, a confound to be controlled with parallel MAP3K8 measurement. Alanine substitution of the carboxy terminal IKK target serines within the beta-TrCP degron blocks stimulus induced precursor destruction and holds RelA in the cytoplasm. Patient variants from common variable immunodeficiency can be introduced directly to test whether they act through reduced expression or altered processing. Read the p105 to p50 ratio by immunoblot, kappaB binding composition, phospho-ERK kinetics, and immunization responses.',
  'Nfkb1:humanized':
    'Humanization has a narrow but real justification here, and it is mechanistic rather than pharmacological. No approved biologic targets p105 or p50, the Rel homology domain is strongly conserved, and IKK directed compounds act upstream, so a coding swap changes little for drug testing. The argument is variant fidelity. Most patient alleles are nonsense or frameshift changes that lower protein through nonsense mediated decay, and whether decay occurs depends on exon junction placement relative to the premature stop. A complementary DNA knockin removes the introns and abolishes that mechanism, producing a stable truncated protein instead of haploinsufficiency, which is the wrong model. Replace with the human genomic coding region, introns intact, mouse regulatory elements retained. Verify roughly half normal p105 and p50 by immunoblot in heterozygotes, then assess immunization responses and aged inflammatory phenotypes.',
  'Ldlr:conditional-knockout':
    'A germline Ldlr null survives and produces the desired hypercholesterolemia, so a floxed allele is not a rescue from lethality but a tool for tissue attribution: hepatocytes handle most apoB particle clearance, and everything else, adrenal cortex, ovary, macrophage, endothelium, is normally invisible behind that hepatic signal. Flank the exons encoding ligand-binding repeats one through five so that the transcript cannot produce a receptor with residual apoB affinity, rather than trimming the cytoplasmic tail, which leaves a surface-retained binding-competent protein. Alb-Cre or AAV8-TBG-Cre gives hepatocyte-restricted loss, LysM-Cre addresses lesional macrophage uptake, and Cdh5-CreERT2 tests endothelial transcytosis. Watch mosaicism: incomplete hepatic recombination leaves enough receptor to blunt the plasma cholesterol rise, so quantify by DiI-LDL uptake in isolated hepatocytes and surface receptor flow cytometry, not genotype alone. Read out FPLC lipoprotein distribution alongside aortic root lesion area.',
  'Ldlr:knockout':
    'The straight null remains the reference atherosclerosis background because loss is tolerated: animals are viable and fertile, roughly double plasma cholesterol on chow, and become severely hypercholesterolemic on Western diet with an LDL and IDL enriched profile closer to familial hypercholesterolemia than the remnant-dominated pattern of Apoe deficiency. Remove the promoter together with the exons encoding the class A repeats so no truncated ligand-binding fragment is secreted and no alternative start can rescue partial expression. Species limits persist regardless of allele quality, since mice lack cholesteryl ester transfer protein and edit Apob to apoB48; crossing to an Apobec1 null yields apoB100-only particles if the endpoint depends on human-like LDL. Standardize diet start age and duration, then score aortic root and brachiocephalic lesion area, necrotic core fraction, macrophage content, plasma lipids, and FPLC profiles across matched littermates.',
  'Ldlr:knockin':
    'Knockins earn their place here because familial hypercholesterolemia is mechanistically stratified, and only a point mutation preserves the distinction. Transport-defective substitutions in the cysteine-rich repeats or the beta-propeller trap the receptor in the endoplasmic reticulum, binding-defective changes in repeats four and five leave a mature surface protein that cannot hold apoB, and mutation of the tyrosine in the cytoplasmic NPXY motif blocks Ldlrap1 recruitment while surface expression and ligand binding stay intact. Introduce the human substitution at the orthologous mouse codon only after confirming residue conservation, and keep heterozygotes, since receptor dosage is the clinically relevant state. Separate the classes experimentally: endoglycosidase H sensitivity and pulse-chase for maturation arrest, surface biotinylation for delivery, four degree binding versus thirty-seven degree internalization of labeled LDL for uptake, and acid-wash recycling assays for release failure, then anchor all of it to plasma cholesterol.',
  'Ldlr:humanized':
    'Humanization is worth the effort only when the reagent reads primary sequence: guide RNAs and base-editing windows for patient FH mutations, antisense or siRNA against human transcript, and antibodies raised on the human ectodomain all fail against the mouse receptor. Replace the mouse coding exons with the human orthologous sequence while retaining the mouse promoter and sterol regulatory element so SREBP2 control and statin responsiveness remain physiological; a cDNA cassette loses intronic regulation and any splice-based readout. Pair with a humanized Pcsk9 allele if the question is antibody or inhibitor pharmacology, because mouse Pcsk9 and human LDLR bind with non-native affinity across species. Remember that lipoprotein architecture stays murine. Validate with human-specific antibody detection of hepatic receptor, amplicon sequencing for on-target editing frequency, apoB particle clearance kinetics, and cholesterol response to the candidate therapeutic.',
  'Pcsk9:conditional-knockout':
    'Because hepatocytes supply nearly all circulating PCSK9, an Alb-Cre or AAV8-TBG-Cre floxed deletion behaves almost identically to a global null on plasma lipids; its real value is temporal, letting you remove the protein in adults after lipoprotein metabolism has matured. Tissue attribution is the more interesting use. Villin-Cre tests enterocyte PCSK9 and chylomicron output, Ins1-Cre asks whether beta cell PCSK9 governs islet LDL receptor density and insulin secretion, and neural drivers probe local receptor regulation in brain, where the circulating pool does not cross the barrier. Flank the exons encoding the subtilisin-like catalytic domain, since autoprocessing within that fold is required for secretion and its loss eliminates the mature chaperone rather than producing a partial protein. Confirm with plasma PCSK9 immunoassay, membrane-fraction LDL receptor western blots from the targeted tissue, and tissue-specific rather than only systemic cholesterol endpoints.',
  'Pcsk9:knockout':
    'A null is fully tolerated and directly mirrors human loss-of-function carriers: circulating protein is absent, hepatic LDL receptor protein rises severalfold, and plasma cholesterol falls by roughly half, so lifelong questions such as atheroprotection, glucose handling, and lipid-soluble vitamin status can be asked without a conditional. One design constraint dominates interpretation: the receptor is the only substrate that matters for lipids, so a Pcsk9 null crossed onto an Ldlr null shows no cholesterol change, and the useful atherosclerosis background is Apoe deficiency or Western diet alone. Delete the promoter with the first coding exon, or the whole locus, so no truncated species retaining receptor affinity is secreted. Read out plasma protein by immunoassay, hepatic surface receptor by membrane-fraction blotting and DiI-LDL uptake, FPLC lipoprotein distribution, and aortic lesion burden in matched littermate cohorts.',
  'Pcsk9:knockin':
    'Point alleles are how you dissect this protein, because deletion tells you only that it exists. Gain-of-function substitutions at the EGF-A contact surface raise receptor affinity and are dominant, so heterozygotes are the disease-relevant genotype and homozygotes mainly extend the dynamic range. Equally useful are separation-of-function designs: mutating the catalytic triad serine or histidine tests whether any residual proteolysis matters, altering the autoprocessing site blocks exit from the endoplasmic reticulum and asks whether secretion is required for receptor loss, and disrupting the furin-sensitive loop stabilizes the mature protein against inactivation. Verify that the targeted residue is conserved between mouse and human before transplanting a patient variant, since the interaction surface, not the whole fold, must be preserved. Score circulating protein, hepatic receptor abundance, plasma cholesterol in heterozygotes, and responsiveness to statin or receptor-directed intervention.',
  'Pcsk9:humanized':
    'The therapeutic argument is narrow and specific: monoclonal antibodies recognize the catalytic domain surface that grips EGF-A, and siRNA and base-editing reagents read human nucleotide sequence, so neither engages the mouse protein at all. Build the allele as a genomic replacement including the human three prime untranslated region and introns, since a coding-only cassette destroys siRNA and antisense target sites and any splice-disrupting editing strategy. Keep transcription under the endogenous mouse regulatory region so sterol and hepatocyte nuclear factor control persist and statin co-treatment behaves normally. Consider dual humanization with LDLR, because human protein binds the mouse receptor with reduced affinity and a single humanization can understate drug effect. Endpoints should include species-specific immunoassay for circulating protein, free versus drug-bound fractions, hepatic receptor protein, dose and duration of cholesterol lowering, and on-target editing frequency by amplicon sequencing.',
  'Myh6:conditional-knockout':
    'Germline loss kills embryos during cardiac looping, so a floxed allele is the only route to adult phenotypes, and adult deletion is severe rather than subtle because this isoform carries most ventricular contraction in mouse. There is a design trap specific to this gene: the standard cardiac drivers are transcribed from the Myh6 promoter itself, and once cells lose alpha myosin and switch toward beta, that promoter is downregulated, so Cre falls off and unrecombined myocytes persist as escapers. Prefer a driver independent of the locus, such as Tnnt2 or Actn2 based inducible lines or AAV9 delivered cTnT-Cre, and always confirm recombination in isolated myocytes. Flank the promoter and initial coding exons rather than internal motor domain exons, since a truncated head fragment incorporates into thick filaments and acts dominantly. Quantify escaper fraction alongside ventricular geometry and isolated myocyte shortening.',
  'Myh6:knockout':
    'Homozygous deletion is developmentally lethal in mid gestation with failed atrial and ventricular maturation, so the homozygote answers a question about embryonic myosin requirement and nothing about adult physiology. The heterozygote is the genotype worth building here, because human septal defects and adrenergic-responsive cardiomyopathy arise from haploinsufficiency, and a mouse carrying one functional copy is a direct dosage model rather than an approximation. Remove the promoter and the entire coding region so no partial transcript can act dominantly and confound a dosage interpretation. For homozygotes, stage embryos from mid gestation with whole-mount imaging, trabeculation and compact layer histology, and optical mapping of atrial contraction. For heterozygotes, examine interatrial septal anatomy, surface and telemetric electrocardiography for sinus node and conduction abnormalities, and stress responses to dobutamine or aortic banding rather than baseline echocardiography alone.',
  'Myh6:knockin':
    'A knockin is the right instrument when the variant is dominant and mechanistic, but the isoform context must match the patient phenotype. Substitutions in the converter region, the actin-binding surface loops, or the rod coiled-coil can be placed at the conserved orthologous codon and studied in heterozygotes, which is the human genotype. Atrial phenotypes and septal defects translate reasonably, whereas transplanting a variant that causes ventricular disease in humans places it in a fast motor working in a ventricle that patients run on a slow motor, so kinetic conclusions do not transfer cleanly. Tagging is also legitimate here: an in-frame epitope or fluorophore at the carboxy terminus allows thick filament incorporation to be tracked without disturbing the head. Purify myosin from ventricle for actin-activated ATPase and single-molecule motility, then pair with myofibril mechanics, atrial histology, and telemetric electrocardiography.',
  'Myh6:humanized':
    'Straight sequence humanization adds little, because this motor is strongly conserved and no clinical agent reads human MYH6 nucleotides or a uniquely human epitope. The valuable version of the idea is isoform replacement: knock the human MYH7 coding sequence into this locus so the ventricle expresses beta myosin under alpha regulatory control, which converts the mouse heart into a slow-motor system resembling the human ventricle and makes mavacamten and related myosin modulators pharmacologically meaningful. Expect reduced contractile reserve and slowed relaxation at native murine heart rates, so include exercise or dobutamine challenge rather than resting measurements alone. Note also that Myh6 promoter driven Cre transgenes remain active on such an allele and must be accounted for in crosses. Confirm isoform content by protein gel or mass spectrometry, then measure actin-activated ATPase, Mant-ATP chase for super-relaxed state occupancy, and drug dose response.',
  'Myh7:conditional-knockout':
    'Adult cardiac deletion is nearly silent at baseline, since the adult mouse ventricle runs on alpha myosin, and that is precisely the experiment: remove the gene in adults, then impose transverse aortic constriction or pressure overload to ask whether stress reinduction of beta myosin is adaptive or contributes to decompensation. Use an inducible driver, ideally one not transcribed from the neighboring Myh6 promoter, or AAV9 delivered cTnT-Cre. The floxed design needs care because the Mhrt long noncoding RNA is transcribed antisense from this locus and shares its regulatory territory, so a large deletion can remove a chromatin-regulatory element rather than only the myosin. Skeletal muscle is the second application, using Acta1 or Ckmm drivers to strip slow type I fibers in soleus. Endpoints include isoform composition, soleus fiber typing, myofibrillar ATPase, and pressure-volume relations after loading.',
  'Myh7:knockout':
    'Deletion is best understood as a background rather than a disease model. Removing beta myosin gives a ventricle that cannot switch isoforms under load, which turns the null into a clean test of whether reinduction during hypertrophy is protective, and it is the correct control when fetal gene program transcripts are used as a stress readout. It also has honest value outside the heart, since this gene encodes slow type I skeletal myosin, so the null reports on soleus fiber typing, contractile speed, and fatigue resistance. Design the deletion to spare the intergenic region shared with Myh6 and the antisense Mhrt transcription unit, or you will confound the result with altered alpha myosin regulation. Assess embryonic ventricular contraction by imaging during mid gestation, isoform content by protein gel, soleus force-frequency and fatigue, and cardiac response to aortic constriction.',
  'Myh7:knockin':
    'The central problem is expression, not construction: a heterozygous variant placed in the mouse Myh7 locus is largely silent in an adult ventricle that transcribes little of it, which is why historical hypertrophic cardiomyopathy alleles were built in Myh6 instead and why kinetic conclusions from those models must be read with the isoform caveat in mind. Two workable designs exist: place the variant in the mouse locus and combine it with a swap that forces ventricular beta expression, or place the human variant on a humanized coding sequence. Choose the substitution class deliberately, converter and mesa surface changes that destabilize the interacting-heads motif for hypercontractile disease, force-generating region changes for dilated presentations, and rod changes for skeletal myopathy. Read out Mant-ATP chase, loaded in vitro motility, myofibrillar kinetics, wall thickness, myocyte disarray, fibrosis, and rescue by myosin inhibition.',
  'Myh7:humanized':
    'Humanization here is justified by pharmacology rather than by immune epitopes, because small molecule myosin modulators bind an allosteric pocket formed by the converter and relay helices where mouse and human residues differ enough to shift potency. In situ replacement of the mouse coding exons with human sequence keeps regulatory control and the antisense Mhrt unit intact but inherits the low adult ventricular expression of this locus, so pharmacology is often more interpretable when the human coding sequence is installed at the Myh6 locus so that human beta myosin becomes the dominant ventricular motor. Slow skeletal fibers express the allele robustly regardless, making soleus a useful ex vivo pharmacology tissue. Measure compound potency on actin-activated ATPase from purified ventricular myosin, super-relaxed occupancy shift, loaded shortening, fractional shortening under dosing with plasma exposure, and confirm human protein by species-specific detection.',
};

export function getGeneModNote(gene: string, modSlug: string): string | undefined {
  return geneModNotes[`${gene}:${modSlug}`];
}
